import { useState, useMemo, useCallback, useEffect, createContext, useContext } from "react";
import { supabase } from "./supabase";

// ============================================================
// STORAGE SHIM — localStorage drop-in for window.storage API
// Allows the app to run outside of Claude artifacts (Netlify, etc.)
// ============================================================
if (typeof window !== "undefined" && !window.storage) {
  window.storage = {
    get: async (key) => {
      const value = localStorage.getItem(key);
      return value !== null ? { key, value } : null;
    },
    set: async (key, value) => {
      localStorage.setItem(key, value);
      return { key, value };
    },
    delete: async (key) => {
      localStorage.removeItem(key);
      return { key, deleted: true };
    },
    list: async (prefix) => {
      const keys = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!prefix || k.startsWith(prefix)) keys.push(k);
      }
      return { keys };
    },
  };
}

// ============================================================
// AUTH CONTEXT — Supabase magic link authentication
// ============================================================
const AuthContext = createContext(null);
function useAuth() { return useContext(AuthContext); }

function AuthProvider({ children }) {
  const [session, setSession] = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session: s } }) => {
      setSession(s);
      if (s?.user) fetchProfile(s.user.id);
      else setLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, s) => {
      setSession(s);
      if (s?.user) fetchProfile(s.user.id);
      else { setProfile(null); setLoading(false); }
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (uid) => {
    try {
      const { data } = await supabase.from("profiles").select("*").eq("id", uid).single();
      setProfile(data);
    } catch (_) {}
    setLoading(false);
  };

  const signIn = async (email, displayName) => {
    const redirectUrl = window.location.origin;
    const options = { emailRedirectTo: redirectUrl };
    if (displayName && displayName.trim()) {
      options.data = { display_name: displayName.trim() };
      // Remember the chosen name locally so we can apply it after the
      // magic-link round-trip, even for returning users.
      try { localStorage.setItem("dragonrose-pending-name", displayName.trim()); } catch (_) {}
    }
    const { error } = await supabase.auth.signInWithOtp({ email, options });
    return { error };
  };

  const updateDisplayName = async (name) => {
    if (!user || !name || !name.trim()) return { error: { message: "No name provided" } };
    const { error } = await supabase.from("profiles").update({ display_name: name.trim() }).eq("id", user.id);
    if (!error) setProfile(p => p ? { ...p, display_name: name.trim() } : p);
    return { error };
  };

  const signOut = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setProfile(null);
  };

  const user = session?.user || null;
  const isAdmin = profile?.role === "admin";
  const isLoggedIn = !!user;

  // After login, apply any name chosen on the sign-in panel (survives the
  // email round-trip via localStorage) if the profile has no real name yet.
  useEffect(() => {
    if (!user || !profile) return;
    let pending = null;
    try { pending = localStorage.getItem("dragonrose-pending-name"); } catch (_) {}
    if (!pending) return;
    const emailPrefix = (user.email || "").split("@")[0];
    if (!profile.display_name || profile.display_name === emailPrefix) {
      supabase.from("profiles").update({ display_name: pending }).eq("id", user.id).then(({ error }) => {
        if (!error) setProfile(p => p ? { ...p, display_name: pending } : p);
        try { localStorage.removeItem("dragonrose-pending-name"); } catch (_) {}
      });
    } else {
      try { localStorage.removeItem("dragonrose-pending-name"); } catch (_) {}
    }
  }, [user, profile]);

  return (
    <AuthContext.Provider value={{ user, profile, isAdmin, isLoggedIn, loading, signIn, signOut, updateDisplayName }}>
      {children}
    </AuthContext.Provider>
  );
}

function LoginPanel({ onClose }) {
  const { signIn } = useAuth();
  const [email, setEmail] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [sent, setSent] = useState(false);
  const [error, setError] = useState("");
  const [sending, setSending] = useState(false);

  const handleSubmit = async () => {
    if (!email.trim() || !email.includes("@")) { setError("Enter a valid email."); return; }
    setSending(true);
    setError("");
    const { error: err } = await signIn(email.trim(), displayName);
    setSending(false);
    if (err) setError(err.message);
    else setSent(true);
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.75)", zIndex: 2000, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }} onClick={onClose}>
      <div style={{ background: "#1a1a24", border: "2px solid rgba(200,148,63,0.35)", borderRadius: 16, padding: 32, maxWidth: 420, width: "100%" }} onClick={e => e.stopPropagation()}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
          <div style={{ fontFamily: "'Cinzel', serif", fontSize: 18, color: "#c8943f", fontWeight: 700 }}>Enter the Enclave</div>
          <button onClick={onClose} style={{ background: "none", border: "none", color: "#6a6050", fontSize: 20, cursor: "pointer" }}>✕</button>
        </div>

        {sent ? (
          <div>
            <p style={{ color: "#7ec87e", fontFamily: "'Crimson Text', serif", fontSize: 15, lineHeight: 1.8 }}>
              A magic link has been sent to <strong>{email}</strong>. Check your email and click the link to enter.
            </p>
            <p style={{ color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontSize: 13, marginTop: 12 }}>
              You can close this panel — the link will bring you right back{displayName.trim() ? ` as ${displayName.trim()}` : ""}.
            </p>
          </div>
        ) : (
          <div>
            <p style={{ color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontSize: 14, lineHeight: 1.8, marginBottom: 20 }}>
              No password needed. Choose how you'll be known, enter your email, and we'll send a magic link.
            </p>
            <label style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 10, letterSpacing: 1, display: "block", marginBottom: 5 }}>DISPLAY NAME</label>
            <input
              type="text" value={displayName} onChange={e => setDisplayName(e.target.value)}
              onKeyDown={e => e.key === "Enter" && handleSubmit()}
              placeholder="How the Bonded will know you"
              maxLength={40}
              style={{
                width: "100%", padding: "10px 14px", borderRadius: 8, border: "1px solid rgba(200,148,63,0.3)",
                background: "rgba(255,255,255,0.05)", color: "#e8dcc8", fontFamily: "'Crimson Text', serif", fontSize: 15,
                outline: "none", boxSizing: "border-box", marginBottom: 12,
              }}
            />
            <label style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 10, letterSpacing: 1, display: "block", marginBottom: 5 }}>EMAIL</label>
            <input
              type="email" value={email} onChange={e => setEmail(e.target.value)}
              onKeyDown={e => e.key === "Enter" && handleSubmit()}
              placeholder="your@email.com"
              style={{
                width: "100%", padding: "10px 14px", borderRadius: 8, border: "1px solid rgba(200,148,63,0.3)",
                background: "rgba(255,255,255,0.05)", color: "#e8dcc8", fontFamily: "'Crimson Text', serif", fontSize: 15,
                outline: "none", boxSizing: "border-box", marginBottom: 12,
              }}
            />
            {error && <p style={{ color: "#e07070", fontSize: 13, marginBottom: 8 }}>{error}</p>}
            <button onClick={handleSubmit} disabled={sending} style={{
              width: "100%", padding: "10px 0", borderRadius: 8, border: "none", cursor: sending ? "not-allowed" : "pointer",
              background: sending ? "rgba(200,148,63,0.3)" : "linear-gradient(135deg, #c8943f, #a0742f)",
              color: sending ? "#8a7e6a" : "#1a1a2e", fontFamily: "'Cinzel', serif", fontSize: 12, fontWeight: 700, letterSpacing: 1,
            }}>
              {sending ? "Sending…" : "Send Magic Link"}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

