// ============================================================
// GENETICS ENGINE
// ============================================================

const FOOD_LABELS = { "ff": "Greenery", "fF": "Pollen/Meat", "Ff": "Poultry", "FF": "Meat" };
const CLUTCH_LABELS = { "cc": "4", "cC": "5", "Cc": "6", "Ccc": "7", "CC": "10" };
const EGG_LABELS = { "ee": "4", "eeE": "5", "eE": "7", "Ee": "9", "EE": "13", "EEE": "14" };

// Resolve egg display from any allele code — Punnett can produce permutations
// not in EGG_LABELS (e.g. "eEe" instead of "eeE"). Normalize by canonical form.
function resolveEggDisplay(code) {
  if (!code) return "?";
  if (EGG_LABELS[code]) return EGG_LABELS[code];
  // Normalize: sort lowercase before uppercase within same letter (e before E)
  // Count upper/lower and map to canonical form
  const lower = (code.match(/e/g) || []).length;
  const upper = (code.match(/E/g) || []).length;
  const total = lower + upper;
  // Rebuild canonical key: all lowercase first, then uppercase
  const canonical = "e".repeat(lower) + "E".repeat(upper);
  if (EGG_LABELS[canonical]) return EGG_LABELS[canonical];
  // Further fallback: interpolate by upper count / total
  if (total === 2) return upper === 0 ? "4" : upper === 1 ? "7" : "13";
  if (total === 3) return upper === 0 ? "4" : upper === 1 ? "5" : upper === 2 ? "9" : "14";
  return String(upper * 4 + lower); // last resort
}
const MOOD_LABELS = {
  // --- Purebred canon labels ---
  "tt": "Calm", "TT": "Rash/Uncontrolled", "tT": "Shy/Timid", "Tt": "All Knowing",
  "tp": "Shy/Preoccupied", "TO": "Cruel/Overprotective", "to": "Happy/Carefree",
  // --- Cross-breed hybrid combos ---
  "Tp": "Rash/Preoccupied", "pT": "Rash/Preoccupied",
  "To": "Rash/Happy", "oT": "Rash/Happy",
  "OT": "Cruel/Rash",
  "Ot": "Cruel/Calm", "tO": "Cruel/Calm",
  "Oo": "Cruel/Happy", "oO": "Cruel/Happy",
  "Op": "Cruel/Preoccupied", "pO": "Cruel/Preoccupied",
  "OO": "Cruel/Overprotective",
  "ot": "Calm/Happy", "po": "Happy/Preoccupied", "op": "Happy/Preoccupied",
  "pt": "Calm/Preoccupied",
  "oo": "Happy/Carefree", "pp": "Preoccupied",
};

const COLOR_NAMES = {
  G: "Green", W: "White", B: "Blue", R: "Red", Y: "Yellow", P: "Purple",
  L: "Black", b: "brown", z: "bronze", a: "aqua", r: "rainbow", s: "silver", o: "orange",
};

// ============================================================
// IMAGE GENERATION — Flux prompt system
// Each egg carries the full genetics of the creature inside.
// Color percentages are rolled per-egg for organic variation,
// so no two clutchmates share an identical palette.
// ============================================================

// Per-species texture signatures (the canonical brush/surface look)
const TEXTURE_SIGNATURES = {
  earth: "soft pencil-crosshatch shading over a matte carved-stone surface",
  air: "liquid-mercury chrome sheen, smooth and reflective",
  fire: "warm molten swirling texture with a glowing ember surface",
  water: "refracted rippling light across a translucent prismatic surface",
  day: "radiant liquid-gold sheen, sunlit and metallic",
  night: "swirling galaxy-marble texture flecked with scattered starlight",
  rainbow: "smooth pewter-grey body with a subtle pearlescent sheen",
  silver: "polished satin metallic sheen, smooth and lustrous",
};

// Brief body silhouette per species (for creature prompts)
const BODY_SIGNATURES = {
  earth: "sturdy grounded wingless body with hoof-like feet",
  air: "slim lightly-built body with oversized glider wings",
  fire: "lean predatory body with strong angular wings",
  water: "sleek serpentine body with fan-finned tail",
  day: "graceful radiant body with broad wings",
  night: "elegant dark-scaled body with star-flecked wings",
  rainbow: "delicate body with broad butterfly-shaped wings",
  silver: "regal slender body with prismatic membrane wings",
};

// Descriptive Flux-ready color phrases — kept neutral on intensity so the
// rolled shade word ("deep" / "rich" / "bright") supplies that without collision.
const FLUX_COLOR_WORDS = {
  G: "forest green", W: "chrome white", B: "ocean blue",
  R: "molten red", Y: "golden yellow", L: "galaxy black",
  b: "earthy brown", a: "aqua", r: "full rainbow gradient",
  s: "silver", o: "amber orange", z: "bronze",
  P: "royal purple",
};

// ----- Hue/shade randomization: each egg gets unique hex codes -----

function hexToHsl(hex) {
  let h = hex.replace("#", "");
  if (h.length === 3) h = h.split("").map(c => c + c).join("");
  const r = parseInt(h.slice(0, 2), 16) / 255;
  const g = parseInt(h.slice(2, 4), 16) / 255;
  const b = parseInt(h.slice(4, 6), 16) / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let hue = 0, sat = 0; const light = (max + min) / 2;
  if (max !== min) {
    const d = max - min;
    sat = light > 0.5 ? d / (2 - max - min) : d / (max + min);
    if (max === r) hue = (g - b) / d + (g < b ? 6 : 0);
    else if (max === g) hue = (b - r) / d + 2;
    else hue = (r - g) / d + 4;
    hue *= 60;
  }
  return { h: hue, s: sat * 100, l: light * 100 };
}

function hslToHex(h, s, l) {
  h = ((h % 360) + 360) % 360; s = Math.max(0, Math.min(100, s)) / 100; l = Math.max(0, Math.min(100, l)) / 100;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  let r = 0, g = 0, b = 0;
  if (h < 60) { r = c; g = x; }
  else if (h < 120) { r = x; g = c; }
  else if (h < 180) { g = c; b = x; }
  else if (h < 240) { g = x; b = c; }
  else if (h < 300) { r = x; b = c; }
  else { r = c; b = x; }
  const toHex = v => Math.round((v + m) * 255).toString(16).padStart(2, "0");
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

// Per-color jitter ranges (degrees / percent). Neutral colors jitter hue less.
const COLOR_JITTER = {
  R: { h: 14, s: 16, l: 12 }, G: { h: 16, s: 16, l: 12 }, B: { h: 16, s: 16, l: 12 },
  Y: { h: 10, s: 14, l: 10 }, o: { h: 12, s: 14, l: 12 }, a: { h: 14, s: 16, l: 12 },
  b: { h: 12, s: 16, l: 14 }, P: { h: 16, s: 16, l: 12 }, z: { h: 12, s: 16, l: 14 },
  W: { h: 30, s: 8, l: 8 }, L: { h: 30, s: 10, l: 10 }, s: { h: 30, s: 8, l: 10 },
};
const DEFAULT_JITTER = { h: 14, s: 14, l: 12 };

// Roll a unique hex within a color's family, plus a shade word from lightness
function rollColorShade(code) {
  const baseHex = COLOR_HEX[code];
  if (!baseHex || (typeof baseHex === "string" && baseHex.startsWith("linear"))) {
    return { hex: null, shade: "" }; // rainbow / gradient — no single hex
  }
  const base = hexToHsl(baseHex);
  const j = COLOR_JITTER[code] || DEFAULT_JITTER;
  const rand = (range) => (Math.random() * 2 - 1) * range;
  const lFinal = base.l + rand(j.l);
  const hex = hslToHex(base.h + rand(j.h), base.s + rand(j.s), lFinal);

  // Derive a shade word from how the rolled lightness landed vs the base
  const delta = lFinal - base.l;
  const neutral = code === "W" || code === "L" || code === "s";
  let shade = "";
  if (neutral) {
    shade = delta <= -5 ? "soft" : delta >= 6 ? "bright" : "";
  } else {
    shade = delta <= -7 ? "deep" : delta >= 8 ? "bright" : "rich";
  }
  return { hex, shade };
}

// Roll an organic per-egg color distribution from an allele code.
// Dominant (uppercase) and primary-position colors get larger shares;
// recessive (lowercase) colors read as accents. Per-egg jitter ensures
// clutchmates vary naturally. Each color also gets a unique rolled hex.
// Returns [{ code, name, word, shade, hex, pct }] desc by pct.
function rollColorPercentages(colorCode, blend) {
  if (!colorCode) return [];

  // Rainbow NEVER appears on the body — it lives on the wings/attachments only
  // (handled by the membrane system). Strip the rainbow allele before rolling.
  let chars = colorCode.split("").filter(c => c !== "r");

  // If nothing remains (a pure-rainbow code), the body defaults to canon pewter-grey.
  if (chars.length === 0) {
    return [{ code: "pewter", name: "pewter grey", word: "pewter grey", shade: "", hex: "#5a5a64", pct: 100 }];
  }

  // Merge duplicate alleles, tracking the strongest position + case
  const seen = {};
  chars.forEach((c, i) => {
    const isUpper = c === c.toUpperCase() && c.toLowerCase() !== c.toUpperCase();
    const posFactor = i === 0 ? 3.0 : i === 1 ? 2.0 : 1.3;
    const caseFactor = isUpper ? 1.0 : 0.45; // recessive = smaller share
    const weight = posFactor * caseFactor;
    if (!seen[c]) seen[c] = 0;
    seen[c] += weight;
  });

  // Apply per-egg jitter, then normalize to 100
  const entries = Object.entries(seen).map(([code, weight]) => ({
    code,
    weight: weight * (0.8 + Math.random() * 0.4), // ±20% jitter
  }));
  const totalWeight = entries.reduce((s, e) => s + e.weight, 0) || 1;
  let pcts = entries.map(e => {
    const shade = rollColorShade(e.code);
    return {
      code: e.code,
      name: COLOR_NAMES[e.code] || e.code,
      word: FLUX_COLOR_WORDS[e.code] || (COLOR_NAMES[e.code] || e.code),
      shade: shade.shade,
      hex: shade.hex,
      pct: Math.round((e.weight / totalWeight) * 100),
    };
  });

  // If a color blend triggered for this egg, fuse the two blended alleles into a
  // single swatch carrying the blend's poetic name, descriptive prompt, and hex.
  if (blend && blend.isBlended && Array.isArray(blend.blendedPair)) {
    const [c1, c2] = blend.blendedPair;
    const e1 = pcts.find(p => p.code === c1);
    const e2 = pcts.find(p => p.code === c2);
    if (e1 && e2) {
      const merged = {
        code: c1 + c2,
        name: blend.display,            // poetic, e.g. "Seafoam"
        word: blend.prompt,             // descriptive, e.g. "blended green from yellow and blue"
        shade: "",
        hex: blend.hex,
        pct: e1.pct + e2.pct,
        isBlend: true,
      };
      pcts = pcts.filter(p => p !== e1 && p !== e2);
      pcts.push(merged);
    }
  }

  // Fix rounding drift so percentages sum to exactly 100
  pcts.sort((a, b) => b.pct - a.pct);
  const drift = 100 - pcts.reduce((s, p) => s + p.pct, 0);
  if (pcts.length) pcts[0].pct += drift;

  return pcts;
}

// Turn rolled percentages into a natural-language phrase for the prompt.
// Includes the rolled shade word and the generated hex per color.
function colorPercentagesToPhrase(pcts) {
  if (!pcts || !pcts.length) return "";
  return pcts.map(p => {
    const desc = p.shade ? `${p.shade} ${p.word}` : p.word;
    const hex = p.hex ? ` (${p.hex})` : "";
    return `${p.pct}% ${desc}${hex}`;
  }).join(", ");
}

// ----- Wing membrane colors -----
// Maps each canon membrane signature to a base hex + clean Flux phrase.
// Gradient/iridescent membranes have no single hex. Body-palette membranes
// (null) pull their color from the egg's dominant rolled body color.
const MEMBRANE_SIGNATURES = {
  "Mercury / Blue Wash": { hex: "#9fb4cc", word: "mercury blue-wash chrome" },
  "Molten Layered": { hex: "#d4581f", word: "molten layered ember" },
  "Liquid Gold": { hex: "#e8b020", word: "liquid gold" },
  "Wrought-Iron Dark": { hex: "#2e2e3a", word: "wrought-iron" },
  "Warm Amber Gold": { hex: "#e8a020", word: "amber gold" },
  "Deep Cobalt / Electric": { hex: "#1a3fa0", word: "electric cobalt" },
  "Deep Amber Bronze": { hex: "#a86420", word: "amber bronze" },
  "Pale Ice / Frost": { hex: "#d8e2f0", word: "ice-frost" },
  "Rainbow Gradient": { gradient: true, word: "full rainbow gradient" },
  "Iridescent Prismatic": { gradient: true, word: "iridescent prismatic shimmer" },
  "Lunar Rainbow — Silver/Violet Gradient": { gradient: true, word: "lunar silver-violet gradient" },
  "Violet-Gold Iridescent": { gradient: true, word: "violet-gold iridescent shimmer" },
};
const MEMBRANE_JITTER = { h: 12, s: 14, l: 12 };

// Roll the membrane description + hex for an egg's creature.
// bodyPcts = the egg's rolled colorPercentages (used for body-palette membranes).
// Returns { phrase, hex, gradientBg } — gradientBg set for gradient swatches.
function rollMembrane(attachmentColor, bodyPcts) {
  // Body-palette membrane (Earth, Water, Jade, Abyssal): match the dominant body color
  if (!attachmentColor || attachmentColor === "Body Palette" || attachmentColor === "null") {
    const dom = (bodyPcts || []).find(p => p.hex) || (bodyPcts || [])[0];
    if (dom && dom.hex) {
      const desc = dom.shade ? `${dom.shade} ${dom.word}` : dom.word;
      return { phrase: `body-colored membrane matching the ${desc} body (${dom.hex})`, hex: dom.hex };
    }
    if (dom) {
      const desc = dom.shade ? `${dom.shade} ${dom.word}` : dom.word;
      return { phrase: `body-colored membrane matching the ${desc} body`, hex: null, gradientBg: COLOR_HEX.r };
    }
    return { phrase: "body-colored membrane", hex: null };
  }
  const sig = MEMBRANE_SIGNATURES[attachmentColor];
  if (!sig) {
    return { phrase: `${attachmentColor} membrane`, hex: null }; // unknown — pass through
  }
  if (sig.gradient) {
    return { phrase: `${sig.word} membrane`, hex: null, gradientBg: COLOR_HEX.r };
  }
  // Solid membrane — roll a unique hex within its family + a shade word
  const base = hexToHsl(sig.hex);
  const rand = (r) => (Math.random() * 2 - 1) * r;
  const lFinal = base.l + rand(MEMBRANE_JITTER.l);
  const hex = hslToHex(base.h + rand(MEMBRANE_JITTER.h), base.s + rand(MEMBRANE_JITTER.s), lFinal);
  const delta = lFinal - base.l;
  const shade = delta <= -7 ? "deep" : delta >= 8 ? "bright" : "rich";
  return { phrase: `${shade} ${sig.word} membrane (${hex})`, hex };
}

// Determine the texture phrase for an egg's creature (blends hybrid parents)
function getEggTexture(egg) {
  if (egg.speciesKey && TEXTURE_SIGNATURES[egg.speciesKey]) {
    return TEXTURE_SIGNATURES[egg.speciesKey];
  }
  const keys = (egg.parentSpeciesKeys || []).filter(k => TEXTURE_SIGNATURES[k]);
  if (keys.length === 2 && keys[0] !== keys[1]) {
    return `a blend of ${TEXTURE_SIGNATURES[keys[0]]} and ${TEXTURE_SIGNATURES[keys[1]]}`;
  }
  if (keys.length >= 1) return TEXTURE_SIGNATURES[keys[0]];
  return "hand-painted scaled surface";
}

const ART_STYLE_BOILERPLATE = "heavy black outlines with organic line weight variation, hand-painted textured fill, white background";

// Build the copy-ready Flux prompt for the EGG image
function buildEggFluxPrompt(egg) {
  const pcts = egg.colorPercentages || rollColorPercentages(egg.colorCode);
  const colorPhrase = colorPercentagesToPhrase(pcts);
  const texture = getEggTexture(egg);
  const speciesLabel = egg.hybridLabel
    ? `${egg.hybridLabel} hybrid`
    : (egg.speciesKey ? `${SPECIES[egg.speciesKey]?.name || egg.speciesKey}` : "dragon");
  const mutationNote = egg.mutationDef ? `, ${egg.mutationDef.shortName || egg.mutationDef.name} mutation coloration` : "";

  return `dragonrose, a single ${speciesLabel} egg, ${texture}, colored ${colorPhrase}${mutationNote}, smooth ovoid egg shape, ${ART_STYLE_BOILERPLATE}`;
}

// Build the copy-ready Flux prompt for the ADULT CREATURE (consistent with the egg's genetics)
function buildCreatureFluxPrompt(egg) {
  const pcts = egg.colorPercentages || rollColorPercentages(egg.colorCode);
  const colorPhrase = colorPercentagesToPhrase(pcts);
  const texture = getEggTexture(egg);
  const speciesLabel = egg.hybridLabel
    ? `${egg.hybridLabel} hybrid dragon`
    : (egg.speciesKey ? `${SPECIES[egg.speciesKey]?.name || egg.speciesKey}` : "dragon");
  const bodyKey = egg.speciesKey || (egg.parentSpeciesKeys || [])[0];
  const body = BODY_SIGNATURES[bodyKey] || "scaled dragon body";

  // Attachments
  const parts = [];
  const ws = egg.wingShape;
  if (ws && ws.winged) {
    const membranePhrase = egg.membranePhrase || rollMembrane(egg.attachmentColor, pcts).phrase;
    parts.push(`${ws.result || "dragon"} wings with ${membranePhrase}`);
  } else {
    parts.push("wingless");
  }
  if (egg.tailTip?.result) parts.push(`${egg.tailTip.result} tail tip`);
  if (egg.headCrest?.result) parts.push(`${egg.headCrest.result} head crest`);
  if (egg.spineType?.result) parts.push(`${egg.spineType.result} along the spine`);

  const mutationNote = egg.mutationDef ? `, ${egg.mutationDef.shortName || egg.mutationDef.name} mutation coloration` : "";
  const lifecycle = egg.isMetamorphic ? ", metamorphic butterfly-lifecycle dragon" : "";

  return `dragonrose, a ${speciesLabel}, ${body}, ${texture}, colored ${colorPhrase}${mutationNote}, ${parts.join(", ")}${lifecycle}, all four legs visible in a standing pose, ${ART_STYLE_BOILERPLATE}`;
}

// Attach generation data to a freshly bred egg (color roll + membrane + both prompts)
function attachGenerationData(egg) {
  const blend = {
    isBlended: egg.isColorBlended,
    display: egg.colorDisplay,
    prompt: egg.colorPromptName,
    hex: egg.colorBlendHex,
    blendedPair: egg.blendedPair,
  };
  const colorPercentages = rollColorPercentages(egg.colorCode, blend);
  const membrane = rollMembrane(egg.attachmentColor, colorPercentages);
  const withGen = { ...egg, colorPercentages, membranePhrase: membrane.phrase, membraneHex: membrane.hex, membraneGradientBg: membrane.gradientBg || null };
  return {
    ...withGen,
    eggPrompt: buildEggFluxPrompt(withGen),
    creaturePrompt: buildCreatureFluxPrompt(withGen),
  };
}


// ============================================================
// CLUTCH EXPORT — dump full genetics + Flux prompts for a clutch
// ============================================================

function eggSpeciesLabel(egg) {
  if (egg.hybridLabel) return `${egg.hybridLabel} (hybrid)`;
  if (egg.speciesKey && SPECIES[egg.speciesKey]) return SPECIES[egg.speciesKey].name;
  if (egg.wildSpeciesKey && SPECIES[egg.wildSpeciesKey]) return SPECIES[egg.wildSpeciesKey].name;
  return "Dragon";
}

function eggPaletteLine(egg) {
  const pcts = egg.colorPercentages || rollColorPercentages(egg.colorCode);
  return pcts.map(p => {
    const desc = p.shade ? `${p.shade} ${p.name}` : p.name;
    return `${p.pct}% ${desc}${p.hex ? ` ${p.hex}` : ""}`;
  }).join(", ");
}

// Full human-readable export of an entire clutch
function buildClutchTextExport(clutch) {
  const L = [];
  const div = "═".repeat(60);
  L.push("DRAGON ROSE — CLUTCH GENETICS EXPORT");
  L.push(`Clutch: ${clutch.name || "Unnamed"}`);
  if (clutch.hybridLabel) L.push(`Offspring line: ${clutch.hybridLabel}`);
  const when = clutch.date || clutch.createdAt;
  if (when) L.push(`Date: ${new Date(when).toLocaleDateString()}`);
  L.push(`Eggs: ${clutch.eggs.length}`);
  L.push("Trigger word: dragonrose · lora_scale 0.80");
  L.push("");

  clutch.eggs.forEach(egg => {
    L.push(div);
    L.push(`EGG #${egg.eggNum} — ${eggSpeciesLabel(egg)}${egg.claimed && egg.claimedName ? ` · "${egg.claimedName}"` : ""}`);
    L.push("");
    L.push(`Color code: ${egg.colorCode || "—"}`);
    L.push(`Colors: ${egg.colorDisplay || "—"}`);
    L.push(`Palette: ${eggPaletteLine(egg)}`);
    if (egg.membranePhrase) L.push(`Membrane: ${egg.membranePhrase}`);
    L.push(`Food: ${egg.foodDisplay || "—"} · Mood: ${egg.moodDisplay || "—"}`);
    const wing = egg.wingShape?.result || (egg.wingShape?.winged === false ? "Wingless" : "—");
    L.push(`Wings: ${wing}`);
    L.push(`Tail: ${egg.tailTip?.result || "—"} · Crest: ${egg.headCrest?.result || "—"} · Spines: ${egg.spineType?.result || "—"}`);
    if (egg.isMetamorphic || egg.lifecycleStages) L.push(`Lifecycle: ${(egg.lifecycleStages || []).join(" → ") || "metamorphic"}`);
    if (egg.mutationDef) L.push(`Mutation: ${egg.mutationDef.name}`);
    L.push("");
    if (egg.eggPrompt) { L.push("EGG PROMPT:"); L.push(egg.eggPrompt); L.push(""); }
    if (egg.creaturePrompt) { L.push("ADULT CREATURE PROMPT:"); L.push(egg.creaturePrompt); L.push(""); }
  });
  L.push(div);
  return L.join("\n");
}

// Prompts only — for direct batch feeding (egg + creature, blank-line separated)
function buildClutchPromptList(clutch, which) {
  const lines = [];
  clutch.eggs.forEach(egg => {
    if ((which === "egg" || which === "both") && egg.eggPrompt) lines.push(egg.eggPrompt);
    if ((which === "creature" || which === "both") && egg.creaturePrompt) lines.push(egg.creaturePrompt);
  });
  return lines.join("\n\n");
}

// Structured JSON export (programmatic use)
function buildClutchJSON(clutch) {
  return JSON.stringify({
    clutch: clutch.name || "Unnamed",
    line: clutch.hybridLabel || null,
    date: clutch.date || clutch.createdAt || null,
    trigger: "dragonrose",
    loraScale: 0.80,
    eggs: clutch.eggs.map(egg => ({
      eggNum: egg.eggNum,
      species: eggSpeciesLabel(egg),
      colorCode: egg.colorCode,
      colorDisplay: egg.colorDisplay,
      palette: (egg.colorPercentages || rollColorPercentages(egg.colorCode)).map(p => ({
        color: p.name, pct: p.pct, shade: p.shade || null, hex: p.hex || null,
      })),
      membrane: egg.membranePhrase || null,
      membraneHex: egg.membraneHex || null,
      food: egg.foodDisplay, mood: egg.moodDisplay,
      wings: egg.wingShape?.result || null,
      tailTip: egg.tailTip?.result || null,
      headCrest: egg.headCrest?.result || null,
      spines: egg.spineType?.result || null,
      lifecycle: egg.lifecycleStages || null,
      mutation: egg.mutationDef?.name || null,
      eggPrompt: egg.eggPrompt || null,
      creaturePrompt: egg.creaturePrompt || null,
    })),
  }, null, 2);
}

// Trigger a file download from a string
function downloadTextFile(filename, text, mime = "text/plain") {
  const blob = new Blob([text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}



