// Roll mutation allele inheritance between two parents.
// status: "none" | "carrier" | "expressed"
// Returns: "none" | "carrier" | "expressed"
function rollMutationAllele(status1, status2) {
  if (status1 === "none" && status2 === "none") return "none";
  const pool1 = status1 === "expressed" ? ["m","m"] : status1 === "carrier" ? ["+","m"] : ["+","+"];
  const pool2 = status2 === "expressed" ? ["m","m"] : status2 === "carrier" ? ["+","m"] : ["+","+"];
  const a = pool1[Math.floor(Math.random() * pool1.length)];
  const b = pool2[Math.floor(Math.random() * pool2.length)];
  if (a === "m" && b === "m") return "expressed";
  if (a === "m" || b === "m") return "carrier";
  return "none";
}

