// Normalize a pair key for lookup — tries both orderings
function blendKey(c1, c2) {
  const k1 = c1 + c2;
  const k2 = c2 + c1;
  if (COLOR_BLENDS[k1]) return k1;
  if (COLOR_BLENDS[k2]) return k2;
  return null;
}

// Resolve an allele color code into display and prompt strings.
// When allowBlend is true (default for hybrid offspring), eligible
// color pairs have a ~50% chance of producing a blended shade.
// Returns: { display, prompt, hex, isBlended, blendedPair }
function resolveColorBlend(code, allowBlend = true) {
  const chars = code.split("");
  const unique = [...new Set(chars)];

  // Skip blending for single-color codes or rainbow allele
  if (unique.length < 2 || chars.includes("r")) {
    const fallback = interpretColor(code);
    return { display: fallback, prompt: fallback, hex: null, isBlended: false, blendedPair: null };
  }

  if (allowBlend) {
    // Check all unique pairs for blend eligibility
    for (let i = 0; i < unique.length; i++) {
      for (let j = i + 1; j < unique.length; j++) {
        const key = blendKey(unique[i], unique[j]);
        if (key && Math.random() < 0.5) {
          const blend = COLOR_BLENDS[key];
          const remaining = unique.filter(c => c !== unique[i] && c !== unique[j]);
          const accentStr = remaining.length > 0
            ? " with " + remaining.map(c => COLOR_NAMES[c] || c).join("/") + " accents"
            : "";
          return {
            display: blend.display + accentStr,
            prompt: blend.prompt + (remaining.length > 0 ? " with " + remaining.map(c => COLOR_NAMES[c] || c).join("/") + " accents" : ""),
            hex: blend.hex,
            isBlended: true,
            blendedPair: [unique[i], unique[j]],
          };
        }
      }
    }
  }

  const fallback = interpretColor(code);
  return { display: fallback, prompt: fallback, hex: null, isBlended: false, blendedPair: null };
}


function punnettSquare2x2(code1, code2) {
  if (code1.length !== 2 || code2.length !== 2) return null;
  const [a1, a2] = code1.split("");
  const [b1, b2] = code2.split("");
  return [a1 + b1, a1 + b2, a2 + b1, a2 + b2];
}

function punnettSquare3x2(code3, code2) {
  const singles = code3.split("");
  const doubles = [];
  for (let i = 0; i < singles.length; i++) {
    for (let j = i + 1; j < singles.length; j++) {
      doubles.push(singles[i] + singles[j]);
    }
  }
  const top = [...singles, ...doubles];
  const [b1, b2] = code2.split("");
  const results = [];
  top.forEach((t) => {
    results.push(t + b1);
    results.push(t + b2);
  });
  return results;
}

function breedGeneticTrait(code1, code2) {
  if (code1.length === 2 && code2.length === 2) return punnettSquare2x2(code1, code2);
  if (code1.length === 3 && code2.length === 2) return punnettSquare3x2(code1, code2);
  if (code1.length === 2 && code2.length === 3) return punnettSquare3x2(code2, code1);
  if (code1.length === 3 && code2.length === 3) {
    const s1 = code1.split("");
    const d1 = [];
    for (let i = 0; i < s1.length; i++) for (let j = i + 1; j < s1.length; j++) d1.push(s1[i] + s1[j]);
    const top = [...s1, ...d1];
    const s2 = code2.split("");
    const d2 = [];
    for (let i = 0; i < s2.length; i++) for (let j = i + 1; j < s2.length; j++) d2.push(s2[i] + s2[j]);
    const side = [...s2, ...d2];
    const results = [];
    top.forEach((t) => side.forEach((s) => results.push(t + s)));
    return results;
  }
  return [code1];
}

// ============================================================
// INDIVIDUAL / PROXY SYSTEM
// ============================================================

// A "proxy" is the normalized shape both breedDragons and breedIndividuals use.
// Both core species and roster individuals are converted to proxies before breeding.
function speciesProxy(s, speciesKey) {
  const colorCode = (s.colors.primary || "") + (s.colors.secondary || "") + (s.colors.tertiary || "");
  return {
    name: s.name,
    speciesKey: speciesKey || null,
    mutationStatus: "none",
    colorCode,
    foodCode: s.food.code,
    moodCode: s.temperament.code,
    clutchCode: s.clutches.code,
    clutchMax: s.clutches.max,
    eggCode: s.eggs.code,
    eggPer: s.eggs.per,
    wingShape: s.wingShape,
    wingMembrane: s.wingMembrane,
    tailTip: s.tailTip,
    headCrest: s.headCrest,
    spineType: s.spineType,
    isMetamorphic: s.stages?.includes("Caterpillar") || false,
    hasRBLineage: s.stages?.includes("Caterpillar") || false,
  };
}

function rosterEntryToProxy(entry, customHybrids = []) {
  // Use stored hybridKey first (saved at breed time — most reliable)
  // Fall back to looking up hybridLabel in HYBRIDS / customHybrids
  let hybridKey = entry.hybridKey || null;
  if (!hybridKey && entry.hybridLabel) {
    const canonMatch = Object.entries(HYBRIDS).find(([, h]) => h.name === entry.hybridLabel);
    if (canonMatch) {
      hybridKey = canonMatch[0];
    } else {
      const customMatch = customHybrids.find(h => h.name === entry.hybridLabel);
      if (customMatch) hybridKey = customMatch.key;
    }
  }
  // parentKey: the key used for hybrid name resolution when this individual is a parent
  // For pure breeds: speciesKey. For hybrids: their hybridKey.
  const parentKey = entry.speciesKey || hybridKey || null;
  return {
    name: entry.name + (entry.hybridLabel ? ` (${entry.hybridLabel})` : ""),
    speciesKey: entry.speciesKey || null,
    hybridKey,
    parentKey,
    // Stored parentSpeciesKeys passed through so breedTwo can derive generation for any offspring
    storedParentKeys: entry.parentSpeciesKeys || [],
    mutationStatus: entry.mutationStatus || "none",
    colorCode: entry.colorCode,
    foodCode: entry.foodCode,
    moodCode: entry.moodCode,
    clutchCode: entry.clutchCode,
    clutchMax: entry.clutchMax || 4,
    eggCode: entry.eggCode,
    eggPer: parseInt(resolveEggDisplay(entry.eggCode)) || entry.clutchMax || 4,
    wingShape: entry.wingShape,
    wingMembrane: entry.wingMembrane,
    tailTip: entry.tailTip,
    headCrest: entry.headCrest,
    spineType: entry.spineType,
    isMetamorphic: entry.isMetamorphic || false,
    hasRBLineage: entry.hasRBLineage || false,
  };
}

// Convert a breeding result + name + label into a roster entry ready for saving
function resultToRosterEntry(result, name, hybridLabel, mutationStatusOverride, gender) {
  const clutchMax = result.clutchMax || parseInt(CLUTCH_LABELS[result.clutchCode]) || result.clutches || 4;
  const eggPer = parseInt(resolveEggDisplay(result.eggCode)) || parseInt(result.eggDisplay) || result.eggs || 4;
  const resolvedHybridLabel = (hybridLabel !== undefined ? hybridLabel : result.hybridLabel) || "";

  // Derive a stable hybrid key for this entry — used by children as a parentKey when breeding
  // Prefer parentSpeciesKeys from the result (most reliable), then fall back to hybridLabel lookup
  const psKeys = result.parentSpeciesKeys || [];
  let hybridKey = result.hybridKey || null;
  if (!hybridKey && resolvedHybridLabel) {
    const canonMatch = Object.entries(HYBRIDS).find(([, h]) => h.name === resolvedHybridLabel);
    hybridKey = canonMatch ? canonMatch[0] : null;
    // Custom hybrids can't be looked up here without a customHybrids list, but
    // they'll be resolved in rosterEntryToProxy which does have access to customHybrids.
  }

  return {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    name: name.trim(),
    hybridLabel: resolvedHybridLabel.trim(),
    hybridKey,                          // stable key for hybrid lookups (null for pure breeds)
    parentSpeciesKeys: psKeys,          // [kA, kB] keys used to breed this individual
    parentage: result.sameBreed
      ? `${result.species} (Pure)`
      : result.parents || "Unknown",
    savedAt: new Date().toISOString(),
    notes: "",
    gender: gender || "unknown",
    speciesKey: result.speciesKey || null,
    mutationStatus: mutationStatusOverride || result.mutationStatus || "none",
    colorCode: result.colorCode || result.colorCode,
    foodCode: result.foodCode,
    moodCode: result.moodCode,
    clutchCode: result.clutchCode,
    clutchMax,
    eggCode: result.eggCode,
    eggPer,
    wingShape: result.wingShape?.result ?? result.wingShape ?? "none",
    wingMembrane: result.wingMembrane?.allele ?? result.wingMembrane ?? "null",
    tailTip: result.tailTip?.result ?? result.tailTip ?? "Arrow / Spade",
    headCrest: result.headCrest?.result ?? result.headCrest ?? "None",
    spineType: result.spineType?.result ?? result.spineType ?? "None",
    colorDisplay: result.colorDisplay || result.colors || "",
    foodDisplay: result.foodDisplay || result.food || "",
    moodDisplay: result.moodDisplay || result.temperament || "",
    clutchDisplay: result.clutchDisplay || String(clutchMax),
    eggDisplay: result.eggDisplay || result.eggs || "",
    attachmentColor: result.attachmentColor || "Body Palette",
    lifecycleStages: result.lifecycleStages || ["Egg", "Hatchling", "Teen", "Adult"],
    isMetamorphic: result.isMetamorphic || result.rbLifecycle || false,
    hasRBLineage: result.hasRBLineage || result.hasRBParent || false,
  };
}

// ============================================================
// VISUAL TRAIT INHERITANCE ENGINE
// ============================================================

// Membrane allele resolution is INDEPENDENT of wing shape.
// The membrane allele always expresses as attachment color (spines, crest, tail tip).
// If the individual is also winged, it additionally appears on the wing surface.
// "null" allele (Earth/Water) = body palette governs attachment color, but allele is
// still heritable — offspring can receive it and pass a non-null allele forward.

// Normalize a wing shape value from a roster entry — if it's a "Blend: X / Y" string
// (stored from a previous breedTwo result), pick one of the component shapes randomly.
// This represents which allele the individual passes on.
function normalizeWingShape(val) {
  if (!val) return "none";
  if (val === "Wingless") return "none";
  if (val.startsWith("Blend: ")) {
    const parts = val.slice(7).split(" / ").map(s => s.trim()).filter(Boolean);
    return parts[Math.floor(Math.random() * parts.length)] || "none";
  }
  return val;
}

function resolveWingShape(s1, s2) {
  const a = normalizeWingShape(s1.wingShape);
  const b = normalizeWingShape(s2.wingShape);
  if (a === "none" && b === "none") return { result: "Wingless", winged: false, note: "Neither parent has wings — definitively wingless." };
  if (a === "none" && b !== "none") {
    return Math.random() < 0.5
      ? { result: "Wingless", winged: false, note: `50/50 — inherited no wings (${s1.name} null allele).` }
      : { result: b, winged: true, note: `50/50 — inherited ${s2.name}'s wing shape.` };
  }
  if (a !== "none" && b === "none") {
    return Math.random() < 0.5
      ? { result: a, winged: true, note: `50/50 — inherited ${s1.name}'s wing shape.` }
      : { result: "Wingless", winged: false, note: `50/50 — inherited no wings (${s2.name} null allele).` };
  }
  if (a === b) return { result: a, winged: true, note: "Both parents share the same wing shape." };
  return { result: `Blend: ${a} / ${b}`, winged: true, note: "Both parents winged, different shapes — blend expressed. Art stage determines proportion." };
}

function resolveMembraneAllele(s1, s2) {
  // Resolves the membrane allele independently — always produces an attachmentColor.
  // "null" allele = body palette (recessive, passable).
  // Rainbow Gradient = co-dominant (50/50 vs any other non-null allele).
  const a = s1.wingMembrane; // "null", "Mercury / Blue Wash", "Rainbow Gradient", etc.
  const b = s2.wingMembrane;

  let resolved;
  let note;

  if (a === "null" && b === "null") {
    resolved = "null";
    note = "Both parents carry null membrane allele — attachment color follows body palette.";
  } else if (a === "null" && b !== "null") {
    resolved = b;
    note = `${s2.name}'s membrane allele expressed (${s1.name} carries null — passable to offspring).`;
  } else if (b === "null" && a !== "null") {
    resolved = a;
    note = `${s1.name}'s membrane allele expressed (${s2.name} carries null — passable to offspring).`;
  } else if (a === "Rainbow Gradient" || b === "Rainbow Gradient") {
    // Co-dominant — 50/50 between rainbow and other
    const other = a === "Rainbow Gradient" ? b : a;
    if (Math.random() < 0.5) {
      resolved = "Rainbow Gradient";
      note = "Co-dominant Rainbow membrane — full rainbow gradient expressed on attachments (and wings if present).";
    } else {
      resolved = other;
      note = `Co-dominant Rainbow membrane — ${other} expressed this time (rainbow possible in siblings).`;
    }
  } else if (a === b) {
    resolved = a;
    note = "Both parents share the same membrane allele.";
  } else {
    resolved = randomPick([a, b]);
    note = `Membrane allele inherited from one parent (Muddy Buddy Rule applies).`;
  }

  const attachmentColor = resolved === "null" ? "Body Palette" : resolved;
  return { allele: resolved, attachmentColor, note };
}

// Normalize a visual trait value that might be a stored compound string like "Leaf-Fin Arrow or Fan Fin"
function normalizeTraitVal(val) {
  if (!val) return val;
  // Handle "X or Y" (stored from resolveVisualTrait winner/loser display) — shouldn't normally be stored,
  // but defensively: pick randomly from slash/or separated values
  if (val.includes(" / ")) {
    const parts = val.split(" / ").map(s => s.trim());
    return parts[Math.floor(Math.random() * parts.length)];
  }
  return val;
}

function resolveVisualTrait(traitName, valA, valB, parentNameA, parentNameB) {
  const a = normalizeTraitVal(valA);
  const b = normalizeTraitVal(valB);
  if (a === b) return { result: a, note: `Both parents share the same ${traitName}.` };
  const winner = randomPick([a, b]);
  const loser = winner === a ? b : a;
  const winnerParent = winner === a ? parentNameA : parentNameB;
  return { result: winner, note: `${winnerParent}'s ${traitName} expressed (${loser} possible in siblings).` };
}

function interpretColor(code) {
  const chars = code.split("");
  const uppers = chars.filter((c) => c === c.toUpperCase() && c !== c.toLowerCase());
  const lowers = chars.filter((c) => c === c.toLowerCase() && c !== c.toUpperCase());
  if (uppers.length === 0 && lowers.length === 0) return chars.map((c) => COLOR_NAMES[c] || c).join("/");
  if (uppers.length > 0 && lowers.length === 0) return chars.map((c) => COLOR_NAMES[c] || c).join("/");
  if (uppers.length > 0 && lowers.length > 0)
    return uppers.map((c) => COLOR_NAMES[c] || c).join("/") + " (with " + lowers.map((c) => COLOR_NAMES[c] || c).join("/") + " accents)";
  return chars.map((c) => COLOR_NAMES[c] || c).join("/");
}

function randomPick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

// Core breeding logic — accepts two proxy objects and optional customHybrids list.
function breedTwo(p1, p2, customHybrids = []) {
  const colorResults = breedGeneticTrait(p1.colorCode, p2.colorCode);
  const foodResults = breedGeneticTrait(p1.foodCode, p2.foodCode);
  const moodResults = breedGeneticTrait(p1.moodCode, p2.moodCode);
  const clutchResults = breedGeneticTrait(p1.clutchCode, p2.clutchCode);
  const eggResults = breedGeneticTrait(p1.eggCode, p2.eggCode);

  const sampledColor = randomPick(colorResults || [p1.colorCode]);
  const sampledFood = randomPick(foodResults || [p1.foodCode]);
  const sampledMood = randomPick(moodResults || [p1.moodCode]);
  const sampledClutch = randomPick(clutchResults || [p1.clutchCode]);
  const sampledEgg = randomPick(eggResults || [p1.eggCode]);

  const wingShapeResult = resolveWingShape(p1, p2);
  const membraneResult = resolveMembraneAllele(p1, p2);
  const tailTipResult = resolveVisualTrait("tail tip", p1.tailTip, p2.tailTip, p1.name, p2.name);
  const headCrestResult = resolveVisualTrait("head crest", p1.headCrest, p2.headCrest, p1.name, p2.name);
  const spineTypeResult = resolveVisualTrait("spine type", p1.spineType, p2.spineType, p1.name, p2.name);

  const isWinged = wingShapeResult.winged;
  const hasRBLineage = p1.hasRBLineage || p2.hasRBLineage || p1.isMetamorphic || p2.isMetamorphic;
  const isMetamorphic = hasRBLineage && Math.random() < 0.5;
  const lifecycleStages = isMetamorphic
    ? ["Egg", "Caterpillar", "Cocoon", "Adult"]
    : ["Egg", "Hatchling", "Teen", "Adult"];
  const clutchMax = parseInt(CLUTCH_LABELS[sampledClutch]) || Math.max(p1.clutchMax, p2.clutchMax) || 4;

  // Mutation rolling — only when both parents share the same pure-breed lineage
  const sharedSpecies = p1.speciesKey && p1.speciesKey === p2.speciesKey ? p1.speciesKey : null;
  const mutationDef = sharedSpecies ? MUTATIONS[sharedSpecies] : null;
  const mutationStatus = (sharedSpecies && (p1.mutationStatus !== "none" || p2.mutationStatus !== "none"))
    ? rollMutationAllele(p1.mutationStatus, p2.mutationStatus)
    : "none";

  // Detect hybrid name — use parentKey (speciesKey or hybridKey) so hybrid roster parents work too
  const p1Key = p1.parentKey || p1.speciesKey || null;
  const p2Key = p2.parentKey || p2.speciesKey || null;
  const hybridLabel = (!sharedSpecies && p1Key && p2Key)
    ? resolveHybridName(p1Key, p2Key, customHybrids) || ""
    : "";

  // Apply palette override if mutation expressed
  const mutationApplied = mutationStatus === "expressed" && mutationDef;
  // Color blending — eligible hybrid color pairs have a 50% chance to fuse.
  // Same-breed pairings skip blending (allowBlend = false).
  const blendInfo = resolveColorBlend(sampledColor, !sharedSpecies);
  const colorDisplayFinal = mutationApplied
    ? mutationDef.colorDisplay
    : blendInfo.display;
  const wingMembraneFinal = mutationApplied && mutationDef.wingMembrane !== "Body Palette"
    ? mutationDef.wingMembrane
    : null; // handled below

  return {
    sameBreed: false,
    parents: `${p1.name} × ${p2.name}`,
    speciesKey: sharedSpecies,
    hybridLabel,
    parentSpeciesKeys: [p1Key, p2Key],
    // Allele codes (for saving to roster)
    colorCode: sampledColor,
    foodCode: sampledFood,
    moodCode: sampledMood,
    clutchCode: sampledClutch,
    clutchMax,
    eggCode: sampledEgg,
    // Display values
    colorDisplay: colorDisplayFinal,
    isColorBlended: mutationApplied ? false : blendInfo.isBlended,
    colorPromptName: mutationApplied ? mutationDef.colorDisplay : blendInfo.prompt,
    colorBlendHex: mutationApplied ? null : blendInfo.hex,
    blendedPair: mutationApplied ? null : blendInfo.blendedPair,
    foodDisplay: FOOD_LABELS[sampledFood] || sampledFood,
    moodDisplay: MOOD_LABELS[sampledMood] || sampledMood,
    clutchDisplay: CLUTCH_LABELS[sampledClutch] || sampledClutch,
    eggDisplay: resolveEggDisplay(sampledEgg),
    // Visual traits (result objects for display)
    wingShape: wingShapeResult,
    wingMembrane: {
      allele: mutationApplied && wingMembraneFinal ? wingMembraneFinal : membraneResult.allele,
      attachmentColor: mutationApplied && wingMembraneFinal ? wingMembraneFinal : membraneResult.attachmentColor,
      onWings: isWinged,
      result: mutationApplied && wingMembraneFinal
        ? wingMembraneFinal
        : isWinged
          ? membraneResult.allele === "null" ? "Body Palette (null allele)" : membraneResult.attachmentColor
          : `Unexpressed on wings — allele carried: ${membraneResult.allele === "null" ? "null (body palette)" : membraneResult.attachmentColor}`,
      note: mutationApplied ? `${mutationDef.name} mutation — full palette shift applied.` : membraneResult.note + (isWinged ? "" : " Allele is heritable and will pass to offspring."),
    },
    attachmentColor: mutationApplied && wingMembraneFinal ? wingMembraneFinal : membraneResult.attachmentColor,
    tailTip: tailTipResult,
    headCrest: headCrestResult,
    spineType: spineTypeResult,
    allColorOutcomes: colorResults,
    allFoodOutcomes: foodResults,
    // Lifecycle
    isMetamorphic,
    rbLifecycle: isMetamorphic,
    lifecycleStages,
    hasRBLineage,
    hasRBParent: hasRBLineage,
    // Mutation
    mutationStatus,
    mutationDef: mutationApplied ? mutationDef : null,
    mutationPalette: mutationApplied ? mutationDef.palette : null,
  };
}

function breedDragons(species1Key, species2Key) {
  const s1 = SPECIES[species1Key];
  const s2 = SPECIES[species2Key];
  if (!s1 || !s2) return null;

  if (species1Key === species2Key) {
    const colorCode = (s1.colors.primary || "") + (s1.colors.secondary || "") + (s1.colors.tertiary || "");
    const isMetamorphic = s1.stages?.includes("Caterpillar") || false;
    return {
      sameBreed: true,
      speciesKey: species1Key,
      parentSpeciesKeys: [species1Key, species1Key],
      species: s1.name,
      note: "Same-breed pairing: offspring inherit parent breed's standard genetics.",
      colors: s1.colors.display.join(", "),
      food: s1.food.label,
      temperament: s1.temperament.label,
      clutches: s1.clutches.max,
      eggs: s1.eggs.per,
      // Allele codes for saving to roster
      colorCode,
      foodCode: s1.food.code,
      moodCode: s1.temperament.code,
      clutchCode: s1.clutches.code,
      clutchMax: s1.clutches.max,
      eggCode: s1.eggs.code,
      wingShape: { result: s1.wingShape, winged: s1.wingShape !== "none", note: "Pure breed." },
      wingMembrane: { allele: s1.wingMembrane, attachmentColor: s1.wingMembrane === "null" ? "Body Palette" : s1.wingMembrane, result: s1.wingMembrane === "null" ? "Body Palette" : s1.wingMembrane, note: "" },
      tailTip: { result: s1.tailTip, note: "" },
      headCrest: { result: s1.headCrest, note: "" },
      spineType: { result: s1.spineType, note: "" },
      attachmentColor: s1.wingMembrane === "null" ? "Body Palette" : s1.wingMembrane,
      colorDisplay: s1.colors.display.join(", "),
      foodDisplay: s1.food.label,
      moodDisplay: s1.temperament.label,
      clutchDisplay: String(s1.clutches.max),
      eggDisplay: String(s1.eggs.per),
      lifecycleStages: s1.stages || ["Egg", "Hatchling", "Teen", "Adult"],
      isMetamorphic,
      rbLifecycle: isMetamorphic,
      hasRBLineage: isMetamorphic,
      hasRBParent: isMetamorphic,
    };
  }

  return breedTwo(speciesProxy(s1, species1Key), speciesProxy(s2, species2Key));
}

// Auto-generate possible traits for a new hybrid from two parent species keys
function generateHybridTraits(keyA, keyB, customHybrids = []) {
  // Resolve each key to a SPECIES entry — direct lookup or via base species resolution
  const resolveToSpecies = (key) => {
    if (SPECIES[key]) return SPECIES[key];
    // For hybrid keys, resolve all base species and return the first one found
    // (we'll merge data from all base species below)
    return null;
  };

  // Gather all base species for each parent
  const baseA = SPECIES[keyA] ? [SPECIES[keyA]] : [...resolveBaseSpecies(keyA, customHybrids)].map(k => SPECIES[k]).filter(Boolean);
  const baseB = SPECIES[keyB] ? [SPECIES[keyB]] : [...resolveBaseSpecies(keyB, customHybrids)].map(k => SPECIES[k]).filter(Boolean);

  if (!baseA.length && !baseB.length) return null;

  const allColors = [...new Set([...baseA, ...baseB].flatMap(s => s.colors.display))];
  const foods = [...new Set([...baseA, ...baseB].map(s => s.food.label))];
  const moods = [...new Set([...baseA, ...baseB].map(s => s.temperament.label))];
  const clutchVals = [...baseA, ...baseB].map(s => s.clutches.max);
  const eggVals = [...baseA, ...baseB].map(s => s.eggs.per);

  const clutchLow = Math.min(...clutchVals);
  const clutchHigh = Math.max(...clutchVals);
  const eggLow = Math.min(...eggVals);
  const eggHigh = Math.max(...eggVals);

  const aWinged = [...baseA].some(s => s.wingShape !== "none");
  const bWinged = [...baseB].some(s => s.wingShape !== "none");
  let wingNote = "";
  if (aWinged && bWinged) wingNote = "Likely winged — both parent lines have wings.";
  else if (!aWinged && !bWinged) wingNote = "Always wingless — no wings in either parent line.";
  else wingNote = "May or may not be winged — mixed wing heritage (50/50 chance).";

  const parentAName = SPECIES[keyA]?.name || HYBRIDS[keyA]?.name || keyA;
  const parentBName = SPECIES[keyB]?.name || HYBRIDS[keyB]?.name || keyB;

  return {
    colorStr: allColors.slice(0, 5).join(", "),
    foodStr: foods.join(" or "),
    temperamentStr: moods.join(" or "),
    clutchStr: clutchLow === clutchHigh ? String(clutchLow) : `${clutchLow}–${clutchHigh}`,
    eggStr: eggLow === eggHigh ? String(eggLow) : `${eggLow} or ${eggHigh}`,
    habitatStr: [...new Set([...baseA, ...baseB].map(s => s.habitat).filter(Boolean))].join(", ") || "Variable",
    wingNote,
    parentA: parentAName,
    parentB: parentBName,
  };
}

// ============================================================
// DRAGON ROSTER — persistent individual registry + custom hybrids
// ============================================================

const RosterContext = createContext(null);

function RosterProvider({ children }) {
  const [roster, setRoster] = useState([]);
  const [customHybrids, setCustomHybrids] = useState([]);
  const [pairs, setPairs] = useState([]);
  const [wildClutches, setWildClutches] = useState([]);
  const [partners, setPartners] = useState([]);
  const [discoveredHybrids, setDiscoveredHybrids] = useState(new Set());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    async function load() {
      try { const r = await window.storage.get("dragon-roster"); if (r?.value) setRoster(JSON.parse(r.value)); } catch (_) {}
      try { const h = await window.storage.get("dragon-custom-hybrids"); if (h?.value) setCustomHybrids(JSON.parse(h.value)); } catch (_) {}
      try { const p = await window.storage.get("dragon-pairs"); if (p?.value) setPairs(JSON.parse(p.value)); } catch (_) {}
      try { const w = await window.storage.get("dragon-wild-clutches"); if (w?.value) setWildClutches(JSON.parse(w.value)); } catch (_) {}
      try { const pt = await window.storage.get("dragon-partners"); if (pt?.value) setPartners(JSON.parse(pt.value)); } catch (_) {}
      try { const d = await window.storage.get("dragon-discovered-hybrids"); if (d?.value) setDiscoveredHybrids(new Set(JSON.parse(d.value))); } catch (_) {}
      setLoaded(true);
    }
    load();
  }, []);

  const persistRoster = async (next) => { setRoster(next); try { await window.storage.set("dragon-roster", JSON.stringify(next)); } catch (_) {} };
  const persistHybrids = async (next) => { setCustomHybrids(next); try { await window.storage.set("dragon-custom-hybrids", JSON.stringify(next)); } catch (_) {} };
  const persistPairs = async (next) => { setPairs(next); try { await window.storage.set("dragon-pairs", JSON.stringify(next)); } catch (_) {} };
  const persistWildClutches = async (next) => { setWildClutches(next); try { await window.storage.set("dragon-wild-clutches", JSON.stringify(next)); } catch (_) {} };
  const persistPartners = async (next) => { setPartners(next); try { await window.storage.set("dragon-partners", JSON.stringify(next)); } catch (_) {} };

  // Discover a hybrid by name — finds its canon key and marks it seen
  const discoverHybrid = (hybridName) => {
    if (!hybridName) return;
    const canonEntry = Object.entries(HYBRIDS).find(([, h]) => h.name === hybridName);
    const key = canonEntry ? canonEntry[0] : null;
    if (!key || discoveredHybrids.has(key)) return;
    const next = new Set(discoveredHybrids);
    next.add(key);
    setDiscoveredHybrids(next);
    try { window.storage.set("dragon-discovered-hybrids", JSON.stringify([...next])); } catch (_) {}
  };

  const addToRoster = (entry) => { persistRoster([...roster, entry]); };
  const removeFromRoster = (id) => { persistRoster(roster.filter((d) => d.id !== id)); };
  const updateRoster = (id, patch) => { persistRoster(roster.map((d) => d.id === id ? { ...d, ...patch } : d)); };

  const addCustomHybrid = (entry) => { persistHybrids([...customHybrids, entry]); };
  const removeCustomHybrid = (key) => { persistHybrids(customHybrids.filter((h) => h.key !== key)); };

  const addPair = (pair) => { persistPairs([...pairs, pair]); };
  const removePair = (id) => { persistPairs(pairs.filter((p) => p.id !== id)); };
  const updatePair = (id, patch) => { persistPairs(pairs.map((p) => p.id === id ? { ...p, ...patch } : p)); };

  const addWildClutch = (clutch) => { persistWildClutches([clutch, ...wildClutches]); };
  const updateWildClutch = (id, patch) => { persistWildClutches(wildClutches.map(c => c.id === id ? { ...c, ...patch } : c)); };
  const removeWildClutch = (id) => { persistWildClutches(wildClutches.filter(c => c.id !== id)); };

  const addPartner = (p) => { persistPartners([...partners, p]); };
  const updatePartner = (id, patch) => { persistPartners(partners.map(p => p.id === id ? { ...p, ...patch } : p)); };
  const removePartner = (id) => { persistPartners(partners.filter(p => p.id !== id)); };

  return (
    <RosterContext.Provider value={{
      roster, customHybrids, pairs, wildClutches, partners, discoveredHybrids, loaded,
      addToRoster, removeFromRoster, updateRoster,
      addCustomHybrid, removeCustomHybrid,
      addPair, removePair, updatePair,
      addWildClutch, updateWildClutch, removeWildClutch,
      addPartner, updatePartner, removePartner,
      discoverHybrid,
    }}>
      {children}
    </RosterContext.Provider>
  );
}

function useRoster() { return useContext(RosterContext); }

// ============================================================
// COMPONENTS
// ============================================================

const speciesOrder = ["earth", "air", "fire", "water", "day", "night", "rainbow", "silver"];

const hybridOrder = [
  // Earth pairs
  "muddybuddy","sandstorm","cinder","marsh","cave","garden","geode",
  // Air pairs (excl. Earth)
  "rain","wildfire","sunbeam","stormcloud","aurora","quicksilver",
  // Fire pairs (excl. Earth, Air)
  "steam","autumn","forge","firefly","crucible",
  // Water pairs (excl. above)
  "tide","deepwater","coral","mist",
  // Day pairs (excl. above)
  "eclipse","sunbow","dusk",
  // Night pairs (excl. above)
  "nightrainbow","void",
  // Rainbow × Silver
  "prism",
  // Gen 2
  "cremementhe","moonmist","fireopal",
];

// Returns palette for any key that might be a species OR a known hybrid
function getParentPalette(key, customHybrids = []) {
  if (SPECIES[key]) return SPECIES[key].palette;
  // Look up in canon HYBRIDS first
  if (HYBRIDS[key]) {
    const h = HYBRIDS[key];
    const p1 = SPECIES[h.parents[0]];
    const p2 = SPECIES[h.parents[1]];
    if (p1 && p2) return { primary: p1.palette.primary, secondary: p2.palette.primary, accent: p1.palette.accent };
    // Parent is itself a hybrid — recurse one level
    const pp1 = getParentPalette(h.parents[0], customHybrids);
    const pp2 = getParentPalette(h.parents[1], customHybrids);
    return { primary: pp1.primary, secondary: pp2.primary, accent: pp1.accent };
  }
  // Check custom hybrids
  const custom = customHybrids.find(h => h.key === key);
  if (custom) {
    const pp1 = getParentPalette(custom.parents[0], customHybrids);
    const pp2 = getParentPalette(custom.parents[1], customHybrids);
    return { primary: pp1.primary, secondary: pp2.primary, accent: pp1.accent };
  }
  return { primary: "#8a7e6a", secondary: "#555", accent: "#c8943f" };
}

function getParentName(key, customHybrids = []) {
  if (SPECIES[key]) return SPECIES[key].name;
  if (HYBRIDS[key]) return HYBRIDS[key].name;
  const custom = customHybrids.find(h => h.key === key);
  if (custom) return custom.name;
  // Last resort: convert snake_case key to Title Case
  return key.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
}

// Returns a solid hex color from a palette — handles gradient strings (RB secondary is the rainbow gradient)
function solidColor(primary, fallback = "#8a7e6a") {
  if (!primary) return fallback;
  const val = typeof primary === "string" ? primary : String(primary);
  if (val.startsWith("linear-gradient") || val.startsWith("radial-gradient")) {
    const match = val.match(/#[0-9a-fA-F]{6}/);
    return match ? match[0] : fallback;
  }
  return val;
}

// Returns the best representative color for UI chrome (pills, borders, filter highlights)
function accentColor(palette) {
  const p = palette?.primary || "";
  if (p.startsWith("linear")) return solidColor(palette?.secondary || "", "#8a7e6a");
  // Use secondary if it's a gradient (RB)
  const s = palette?.secondary || "";
  if (s.startsWith("linear")) return solidColor(s);
  return p || "#8a7e6a";
}

// Recursively resolve all base-8 species that contribute to a hybrid's lineage.
// Returns a Set of species keys (e.g. {"fire","water","earth"} for Creme de Menthe)
function resolveBaseSpecies(key, customHybrids = [], visited = new Set()) {
  if (visited.has(key)) return new Set();
  visited.add(key);
  if (SPECIES[key]) return new Set([key]);
  const hybrid = HYBRIDS[key] || customHybrids.find(h => h.key === key);
  if (!hybrid) return new Set();
  const result = new Set();
  for (const parent of hybrid.parents) {
    for (const s of resolveBaseSpecies(parent, customHybrids, new Set(visited))) {
      result.add(s);
    }
  }
  return result;
}

// Recursively compute the generation number for any hybrid key.
// Base-8 species = 0. Gen 1 hybrid of two species = 1. Gen 2 = max(parent gens) + 1. Etc.
function resolveGeneration(key, customHybrids = [], visited = new Set()) {
  if (visited.has(key)) return 0;
  visited.add(key);
  if (SPECIES[key]) return 0;
  const hybrid = HYBRIDS[key] || customHybrids.find(h => h.key === key);
  if (!hybrid) return 1;
  const parentGens = hybrid.parents.map(p => resolveGeneration(p, customHybrids, new Set(visited)));
  return Math.max(...parentGens) + 1;
}

// Given two species/hybrid keys, return the matching hybrid name (or null).
// Checks canon HYBRIDS first, then any user-created customHybrids.
function resolveHybridName(keyA, keyB, customHybrids = []) {
  const setAB = [keyA, keyB].sort().join("|");
  for (const h of Object.values(HYBRIDS)) {
    const setH = [...h.parents].sort().join("|");
    if (setH === setAB) return h.name;
  }
  for (const h of customHybrids) {
    const setH = [...h.parents].sort().join("|");
    if (setH === setAB) return h.name;
  }
  return null;
}

function ColorSwatch({ colors, palette }) {
  return (
    <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
      {colors.map((c, i) => (
        <span key={i} style={{
          display: "inline-block", padding: "2px 10px", borderRadius: 4, fontSize: 12,
          background: Object.values(palette)[i] || "#666", color: ["Yellow", "White", "Orange", "Aquamarine"].includes(c) ? "#1a1a2e" : "#fff",
          border: "1px solid rgba(255,255,255,0.15)", fontFamily: "'Crimson Text', serif",
        }}>{c}</span>
      ))}
    </div>
  );
}

function StatBar({ label, value, max, color }) {
  return (
    <div style={{ marginBottom: 8 }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 3, fontFamily: "'Crimson Text', serif", color: "#c8b89a" }}>
        <span>{label}</span><span>{value}</span>
      </div>
      <div style={{ height: 6, background: "rgba(255,255,255,0.08)", borderRadius: 3 }}>
        <div style={{ height: "100%", width: `${(value / max) * 100}%`, background: color || "#c8943f", borderRadius: 3, transition: "width 0.6s ease" }} />
      </div>
    </div>
  );
}

function SpeciesCard({ speciesKey, onClick, selected }) {
  const s = SPECIES[speciesKey];
  return (
    <button onClick={() => onClick(speciesKey)} style={{
      background: selected ? "rgba(200,148,63,0.2)" : "rgba(255,255,255,0.04)",
      border: selected ? "1px solid #c8943f" : "1px solid rgba(255,255,255,0.08)",
      borderRadius: 10, padding: "14px 16px", cursor: "pointer", textAlign: "left", transition: "all 0.25s ease",
      transform: selected ? "scale(1.02)" : "scale(1)",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
        <div style={{
          width: 32, height: 32, borderRadius: "50%",
          background: s.palette.secondary?.startsWith?.("linear")
            ? s.palette.secondary
            : s.palette.primary.startsWith?.("linear")
              ? s.palette.primary
              : `linear-gradient(135deg, ${s.palette.primary}, ${s.palette.secondary || s.palette.accent})`,
          border: "2px solid rgba(255,255,255,0.15)", flexShrink: 0,
        }} />
        <div>
          <div style={{ color: "#e8dcc8", fontFamily: "'Cinzel', serif", fontSize: 14, fontWeight: 700 }}>{s.name}</div>
          <div style={{ color: "#8a7e6a", fontSize: 11, fontFamily: "'Crimson Text', serif" }}>{s.rarity} Species</div>
        </div>
      </div>
      <ColorSwatch colors={s.colors.display} palette={s.palette} />
    </button>
  );
}


function SpeciesArtGallery({ speciesKey }) {
  const art = DRAGON_ART[speciesKey];
  if (!art || !art.stages) return null;
  const adult = art.stages.find(s => s.key === "adult");
  if (!adult) return null;
  const s = SPECIES[speciesKey];

  return (
    <div style={{ marginBottom: 24, textAlign: "center" }}>
      <div style={{
        display: "inline-block",
        background: `radial-gradient(ellipse at center, ${accentColor(s.palette)}22, transparent)`,
        borderRadius: 14, padding: 16, border: "1px solid rgba(255,255,255,0.06)",
      }}>
        <img
          src={adult.src}
          alt={`${s.name} Adult`}
          style={{ maxHeight: 160, maxWidth: 180, display: "block", margin: "0 auto", imageRendering: "auto" }}
        />
      </div>
      <div style={{ marginTop: 8, fontSize: 11, fontFamily: "'Cinzel', serif", color: "#8a7e6a", letterSpacing: 2, textTransform: "uppercase" }}>
        Adult
      </div>
    </div>
  );
}

function MutationSection({ speciesKey }) {
  const mut = MUTATIONS[speciesKey];
  if (!mut) return null;
  const [r, g, b] = [
    parseInt(mut.palette.primary.slice(1,3), 16),
    parseInt(mut.palette.primary.slice(3,5), 16),
    parseInt(mut.palette.primary.slice(5,7), 16),
  ];
  return (
    <div style={{ marginTop: 24, paddingTop: 20, borderTop: "1px solid rgba(255,255,255,0.07)" }}>
      <div style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, textTransform: "uppercase", letterSpacing: 2, marginBottom: 12 }}>
        Known Mutation
      </div>
      <div style={{
        background: `rgba(${r},${g},${b},0.08)`,
        border: `1px solid ${mut.palette.primary}44`,
        borderRadius: 10, padding: 16,
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
          <div style={{ display: "flex", gap: 4 }}>
            {Object.values(mut.palette).map((hex, i) => (
              <div key={i} style={{ width: 18, height: 18, borderRadius: "50%", background: hex, border: "1px solid rgba(255,255,255,0.2)" }} />
            ))}
          </div>
          <div style={{ fontFamily: "'Cinzel', serif", fontSize: 14, color: "#e8dcc8", fontWeight: 700 }}>{mut.name}</div>
          <div style={{ fontSize: 11, color: "#8a7e6a", fontFamily: "'Crimson Text', serif" }}>Recessive</div>
        </div>
        <p style={{ margin: "0 0 8px", color: "#b0a890", fontFamily: "'Crimson Text', serif", fontSize: 13, lineHeight: 1.7 }}>
          {mut.description}
        </p>
        <div style={{ fontSize: 12, color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontStyle: "italic" }}>
          🥚 {mut.eggNote}
        </div>
        <div style={{ marginTop: 8, fontSize: 11, color: "#6a6050", fontFamily: "'Cinzel', serif", letterSpacing: 1 }}>
          BREEDING ODDS (carrier × carrier) · 25% expressed · 50% carrier · 25% normal
        </div>
      </div>
    </div>
  );
}

function SpeciesDetail({ speciesKey }) {
  const s = SPECIES[speciesKey];
  if (!s) return null;
  return (
    <div style={{
      background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.08)",
      borderRadius: 12, padding: 28, position: "relative", overflow: "hidden",
    }}>
      <div style={{
        position: "absolute", top: 0, left: 0, right: 0, height: 4,
        background: s.palette.secondary?.startsWith?.("linear")
          ? s.palette.secondary
          : s.palette.primary.startsWith?.("linear")
            ? s.palette.primary
            : `linear-gradient(90deg, ${s.palette.primary}, ${s.palette.accent}, ${s.palette.secondary || s.palette.primary})`,
      }} />
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
        <div style={{
          width: 52, height: 52, borderRadius: "50%",
          background: s.palette.secondary?.startsWith?.("linear")
            ? s.palette.secondary
            : s.palette.primary.startsWith?.("linear")
              ? s.palette.primary
              : `linear-gradient(135deg, ${s.palette.primary}, ${s.palette.secondary || s.palette.accent})`,
          border: "3px solid rgba(255,255,255,0.15)",
        }} />
        <div>
          <h2 style={{ margin: 0, fontFamily: "'Cinzel', serif", fontSize: 24, color: "#e8dcc8" }}>{s.name}</h2>
          <div style={{ color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontSize: 14 }}>{s.rarity} Species</div>
        </div>
      </div>

      <p style={{ color: "#b0a890", fontFamily: "'Crimson Text', serif", fontSize: 15, lineHeight: 1.7, marginBottom: 20, fontStyle: "italic" }}>
        {s.description}
      </p>

      <SpeciesArtGallery speciesKey={speciesKey} />

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 20 }}>
        <div>
          <div style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, textTransform: "uppercase", letterSpacing: 2, marginBottom: 8 }}>Biology</div>
          <div style={{ fontSize: 13, color: "#c8b89a", fontFamily: "'Crimson Text', serif", lineHeight: 1.8 }}>
            <div><strong style={{ color: "#e8dcc8" }}>Body:</strong> {s.body}</div>
            <div><strong style={{ color: "#e8dcc8" }}>Wings:</strong> {s.wings}</div>
            <div><strong style={{ color: "#e8dcc8" }}>Food:</strong> {s.food.label}</div>
            <div><strong style={{ color: "#e8dcc8" }}>Habitat:</strong> {s.habitat}</div>
          </div>
        </div>
        <div>
          <div style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, textTransform: "uppercase", letterSpacing: 2, marginBottom: 8 }}>Personality</div>
          <div style={{ fontSize: 13, color: "#c8b89a", fontFamily: "'Crimson Text', serif", lineHeight: 1.8 }}>
            <div><strong style={{ color: "#e8dcc8" }}>Type:</strong> {s.temperament.label}</div>
            <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginTop: 6 }}>
              {s.temperament.traits.map((t, i) => (
                <span key={i} style={{
                  padding: "2px 8px", borderRadius: 4, fontSize: 11, background: "rgba(200,148,63,0.15)",
                  color: "#c8943f", border: "1px solid rgba(200,148,63,0.25)", fontFamily: "'Crimson Text', serif",
                }}>{t}</span>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, textTransform: "uppercase", letterSpacing: 2, marginBottom: 10 }}>Breeding Stats</div>
      <StatBar label="Max Clutches" value={s.clutches.max} max={10} color={accentColor(s.palette)} />
      <StatBar label="Eggs per Clutch" value={s.eggs.per} max={14} color={s.palette.accent} />

      <div style={{ marginTop: 16 }}>
        <div style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, textTransform: "uppercase", letterSpacing: 2, marginBottom: 8 }}>Life Stages</div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          {s.stages.map((stage, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{
                padding: "4px 12px", borderRadius: 6, fontSize: 12,
                background: `linear-gradient(135deg, ${accentColor(s.palette)}33, ${solidColor(s.palette.accent)}22)`,
                color: "#e8dcc8", border: "1px solid rgba(255,255,255,0.08)", fontFamily: "'Crimson Text', serif",
              }}>{stage}</div>
              {i < s.stages.length - 1 && <span style={{ color: "#555" }}>→</span>}
            </div>
          ))}
        </div>
      </div>

      <div style={{ marginTop: 16 }}>
        <div style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, textTransform: "uppercase", letterSpacing: 2, marginBottom: 8 }}>Genetic Profile</div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
          {[
            { label: "Color", code: (s.colors.primary || "") + (s.colors.secondary || "") + (s.colors.tertiary || "") },
            { label: "Food", code: s.food.code },
            { label: "Mood", code: s.temperament.code },
            { label: "Clutch", code: s.clutches.code },
            { label: "Eggs", code: s.eggs.code },
            { label: "Body", code: s.code },
          ].map((g, i) => (
            <div key={i} style={{
              padding: "6px 12px", borderRadius: 6, fontSize: 12,
              background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.08)",
              fontFamily: "'Courier New', monospace", color: "#c8b89a",
            }}>
              <span style={{ color: "#8a7e6a", fontSize: 10 }}>{g.label}:</span> <span style={{ color: "#e8dcc8" }}>{g.code}</span>
            </div>
          ))}
        </div>
        <div style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, textTransform: "uppercase", letterSpacing: 2, marginBottom: 8 }}>Visual Traits</div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {[
            { label: "Wing Shape", val: s.wingShape },
            { label: "Wing Membrane", val: s.wingMembrane },
            { label: "Tail Tip", val: s.tailTip },
            { label: "Head Crest", val: s.headCrest },
            { label: "Spine Type", val: s.spineType },
          ].filter(g => g.val && g.val !== "none").map((g, i) => (
            <div key={i} style={{
              padding: "6px 12px", borderRadius: 6, fontSize: 12,
              background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.08)",
              fontFamily: "'Crimson Text', serif", color: "#c8b89a",
            }}>
              <span style={{ color: "#8a7e6a", fontSize: 10 }}>{g.label}:</span> <span style={{ color: "#e8dcc8" }}> {g.val}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Mutation section */}
      {MUTATIONS[speciesKey] && (
        <MutationSection speciesKey={speciesKey} />
      )}
    </div>
  );
}

function HybridCard({ hybridKey, customHybrid }) {
  const { removeCustomHybrid, customHybrids = [] } = useRoster() || {};
  const h = customHybrid || HYBRIDS[hybridKey];
  if (!h) return null;
  const isCustom = !!customHybrid;
  const p1palette = getParentPalette(h.parents[0], customHybrids);
  const p2palette = getParentPalette(h.parents[1], customHybrids);
  const p1name = getParentName(h.parents[0], customHybrids);
  const p2name = getParentName(h.parents[1], customHybrids);
  return (
    <div style={{
      background: isCustom ? "rgba(180,140,200,0.05)" : "rgba(255,255,255,0.03)",
      border: isCustom ? "1px solid rgba(180,140,200,0.25)" : "1px solid rgba(255,255,255,0.08)",
      borderRadius: 10, padding: 20, position: "relative", overflow: "hidden",
    }}>
      <div style={{
        position: "absolute", top: 0, left: 0, right: 0, height: 3,
        background: `linear-gradient(90deg, ${solidColor(p1palette.primary)}, ${solidColor(p2palette.primary)})`,
      }} />
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 10 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{ display: "flex" }}>
            <div style={{ width: 24, height: 24, borderRadius: "50%", background: p1palette.primary, border: "2px solid rgba(0,0,0,0.3)" }} />
            <div style={{ width: 24, height: 24, borderRadius: "50%", background: p2palette.primary, border: "2px solid rgba(0,0,0,0.3)", marginLeft: -8 }} />
          </div>
          <div>
            <div style={{ fontFamily: "'Cinzel', serif", fontSize: 15, color: "#e8dcc8", fontWeight: 700 }}>
              {h.name}
              {isCustom && <span style={{ fontSize: 10, color: "#c090d8", marginLeft: 8, letterSpacing: 1 }}>NEW</span>}
            </div>
            <div style={{ fontSize: 11, color: "#8a7e6a", fontFamily: "'Crimson Text', serif" }}>
              Gen {h.parents
                ? Math.max(resolveGeneration(h.parents[0], customHybrids), resolveGeneration(h.parents[1], customHybrids)) + 1
                : h.generation} · {p1name} + {p2name}
            </div>
          </div>
        </div>
        {isCustom && removeCustomHybrid && (
          <button onClick={() => removeCustomHybrid(h.key)} style={{ background: "none", border: "none", cursor: "pointer", color: "#5a4a3a", fontSize: 14, padding: "2px 4px" }} title="Remove">✕</button>
        )}
      </div>
      <p style={{ color: "#b0a890", fontFamily: "'Crimson Text', serif", fontSize: 13, lineHeight: 1.6, margin: "0 0 10px" }}>{h.description}</p>
      <div style={{ fontSize: 12, color: "#c8b89a", fontFamily: "'Crimson Text', serif", lineHeight: 1.7 }}>
        <div><strong style={{ color: isCustom ? "#c090d8" : "#c8943f" }}>Colors:</strong> {h.colors}</div>
        <div><strong style={{ color: isCustom ? "#c090d8" : "#c8943f" }}>Food:</strong> {h.food}</div>
        <div><strong style={{ color: isCustom ? "#c090d8" : "#c8943f" }}>Temperament:</strong> {h.temperament}</div>
        <div><strong style={{ color: isCustom ? "#c090d8" : "#c8943f" }}>Habitat:</strong> {h.habitat}</div>
        <div><strong style={{ color: isCustom ? "#c090d8" : "#c8943f" }}>Clutches:</strong> {h.clutches} · <strong style={{ color: isCustom ? "#c090d8" : "#c8943f" }}>Eggs:</strong> {h.eggs}</div>
        {isCustom && h.wingNote && <div style={{ marginTop: 4, fontSize: 11, color: "#7a7060", fontStyle: "italic" }}>{h.wingNote}</div>}
      </div>
    </div>
  );
}

function MutationBadge({ status, mutationDef, speciesKey, size = "normal" }) {
  if (!status || status === "none") return null;
  const def = mutationDef || (speciesKey ? MUTATIONS[speciesKey] : null);
  if (!def) return null;
  const isExpressed = status === "expressed";
  const color = isExpressed ? "#f0c820" : "#8a7e6a";
  const bg = isExpressed ? "rgba(240,200,32,0.15)" : "rgba(255,255,255,0.06)";
  const border = isExpressed ? "rgba(240,200,32,0.4)" : "rgba(255,255,255,0.12)";
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 4,
      padding: size === "small" ? "1px 7px" : "2px 10px",
      borderRadius: 20, border: `1px solid ${border}`, background: bg,
      color, fontFamily: "'Cinzel', serif",
      fontSize: size === "small" ? 10 : 11, letterSpacing: 1,
    }}>
      {isExpressed ? "✦" : "◇"} {isExpressed ? def.name : `${def.shortName} Carrier`}
    </span>
  );
}

function SpecSheetBlock({ data, name }) {
  // data can be a roster entry or a breedDragons/breedTwo result
  // name is displayed at the top; falls back to data.name
  const displayName = name || data?.name || "Unnamed Dragon";
  if (!data) return null;

  const isSame = data.sameBreed;
  const timestamp = data.savedAt || data.timestamp || new Date().toISOString();

  // Resolve fields that may come from either roster entry or result object
  const parentage    = isSame ? `${data.species} (Pure)` : (data.parentage || data.parents || "Unknown");
  const colorDisplay = data.colorDisplay || data.colors || "";
  const colorCode    = data.colorCode || "";
  const foodDisplay  = data.foodDisplay || data.food || "";
  const foodCode     = data.foodCode || "";
  const moodDisplay  = data.moodDisplay || data.temperament || "";
  const moodCode     = data.moodCode || "";
  const clutchDisplay= data.clutchDisplay || String(data.clutches || "");
  const clutchCode   = data.clutchCode || "";
  const eggDisplay   = data.eggDisplay || String(data.eggs || "");
  const eggCode      = data.eggCode || "";
  const wingShape    = data.wingShape?.result ?? data.wingShape ?? "—";
  const membrane     = data.wingMembrane?.result ?? data.wingMembrane ?? "—";
  const attachColor  = data.attachmentColor || "Body Palette";
  const tailTip      = data.tailTip?.result ?? data.tailTip ?? "—";
  const headCrest    = data.headCrest?.result ?? data.headCrest ?? "—";
  const spineType    = data.spineType?.result ?? data.spineType ?? "—";
  const hybridLabel  = data.hybridLabel || "";
  const gender       = data.gender;
  const lifecycle    = data.lifecycleStages?.join(" → ") || "Egg → Hatchling → Teen → Adult";
  const mutStatus    = data.mutationStatus;
  const mutDef       = data.speciesKey ? MUTATIONS[data.speciesKey] : null;

  const lineStyle = { marginBottom: 2 };

  return (
    <div style={{
      background: "#1a1a1e", border: "2px solid #c8943f", borderRadius: 12, padding: 24,
      fontFamily: "'Courier New', monospace", fontSize: 12, color: "#c8b89a", lineHeight: 1.9,
    }}>
      {/* Header */}
      <div style={{ textAlign: "center", marginBottom: 16 }}>
        <div style={{ fontFamily: "'Cinzel', serif", fontSize: 18, color: "#c8943f", fontWeight: 700, letterSpacing: 2 }}>DRAGON ROSE ADOPTIONS</div>
        <div style={{ fontSize: 10, color: "#8a7e6a", letterSpacing: 3, textTransform: "uppercase" }}>Official Spec Sheet</div>
        <div style={{ width: 60, height: 1, background: "#c8943f", margin: "8px auto" }} />
      </div>

      {/* Identity */}
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>NAME: </span><span style={{ color: "#e8dcc8" }}>{displayName}</span>
        {gender && gender !== "unknown" && <span style={{ color: gender === "female" ? "#e090c0" : "#90a8e0", marginLeft: 8 }}>{gender === "female" ? "♀" : "♂"}</span>}
      </div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>BREED: </span>{hybridLabel || parentage}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>PARENTAGE: </span>{parentage}</div>

      {/* Genetics */}
      <div style={{ marginTop: 10, marginBottom: 4, color: "#c8943f", fontSize: 10, letterSpacing: 3 }}>— GENETICS —</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>COLORS: </span>{colorDisplay}{colorCode && <span style={{ color: "#555" }}> [{colorCode}]</span>}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>FOOD: </span>{foodDisplay}{foodCode && <span style={{ color: "#555" }}> [{foodCode}]</span>}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>TEMPERAMENT: </span>{moodDisplay}{moodCode && <span style={{ color: "#555" }}> [{moodCode}]</span>}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>MAX CLUTCHES: </span>{clutchDisplay}{clutchCode && <span style={{ color: "#555" }}> [{clutchCode}]</span>}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>EGGS/CLUTCH: </span>{eggDisplay}{eggCode && <span style={{ color: "#555" }}> [{eggCode}]</span>}</div>

      {/* Visual traits */}
      <div style={{ marginTop: 10, marginBottom: 4, color: "#c8943f", fontSize: 10, letterSpacing: 3 }}>— VISUAL TRAITS —</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>WING SHAPE: </span>{wingShape}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>MEMBRANE: </span>{membrane}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>ATTACHMENT COLOR: </span>{attachColor} <span style={{ color: "#555" }}>(tail · crest · spines)</span></div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>TAIL TIP: </span>{tailTip}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>HEAD CREST: </span>{headCrest}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>SPINE TYPE: </span>{spineType}</div>
      <div style={lineStyle}><span style={{ color: "#8a7e6a" }}>LIFECYCLE: </span>{lifecycle}</div>

      {/* Mutation */}
      {mutStatus && mutStatus !== "none" && mutDef && (
        <div style={lineStyle}>
          <span style={{ color: "#8a7e6a" }}>MUTATION: </span>
          <span style={{ color: mutStatus === "expressed" ? "#f0c820" : "#8a7e6a" }}>
            {mutStatus === "expressed" ? `✦ ${mutDef.name} (expressed)` : `◇ ${mutDef.shortName} Carrier`}
          </span>
        </div>
      )}

      {/* Footer */}
      <div style={{ marginTop: 12, paddingTop: 10, borderTop: "1px dashed rgba(200,148,63,0.3)", fontSize: 10, color: "#6a6050" }}>
        <div>Generated: {new Date(timestamp).toLocaleString()}</div>
        <div>Canon Compliant · Dragon Rose Reconstruction v1.0</div>
      </div>
    </div>
  );
}

// Standalone registration block — shown when a cross has no known hybrid name
function RegisterHybridBlock({ parentKeys, customHybrids = [], onRegistered }) {
  const { addCustomHybrid } = useRoster() || {};
  const [open, setOpen] = useState(false);
  const [regName, setRegName] = useState("");
  const [regDesc, setRegDesc] = useState("");
  const [done, setDone] = useState(false);

  const [kA, kB] = parentKeys || [];
  if (!kA || !kB) return null;

  // Already registered (could have been added this session)
  const alreadyNamed = resolveHybridName(kA, kB, customHybrids);
  if (alreadyNamed) return null;

  const traits = generateHybridTraits(kA, kB, customHybrids);

  const handleRegister = () => {
    if (!regName.trim()) return;
    const finalName = regName.trim().endsWith(" Dragon") ? regName.trim() : `${regName.trim()} Dragon`;
    const key = finalName.toLowerCase().replace(/\s+/g, "_").replace(/[^a-z0-9_]/g, "");
    const entry = {
      key,
      name: finalName,
      parents: [kA, kB],
      generation: Math.max(resolveGeneration(kA, customHybrids), resolveGeneration(kB, customHybrids)) + 1,
      custom: true,
      description: regDesc.trim() || `A newly discovered hybrid between ${traits?.parentA || kA} and ${traits?.parentB || kB}.`,
      colors: traits?.colorStr || "Variable",
      food: traits?.foodStr || "Variable",
      temperament: traits?.temperamentStr || "Variable",
      clutches: traits?.clutchStr || "Variable",
      eggs: traits?.eggStr || "Variable",
      habitat: traits?.habitatStr || "Variable",
      wingNote: traits?.wingNote || "",
    };
    addCustomHybrid(entry);
    setDone(true);
    setOpen(false);
    if (onRegistered) onRegistered(entry);
  };

  if (done) {
    return (
      <div style={{ padding: "8px 12px", borderRadius: 8, background: "rgba(180,140,200,0.08)", border: "1px solid rgba(180,140,200,0.25)", marginBottom: 10, fontSize: 11, color: "#c090d8", fontFamily: "'Cinzel', serif", letterSpacing: 1 }}>
        ✦ New hybrid type registered — visible in the Hybrids tab.
      </div>
    );
  }

  return (
    <div style={{ marginBottom: 10 }}>
      {!open ? (
        <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 12px", borderRadius: 8, background: "rgba(180,140,200,0.06)", border: "1px dashed rgba(180,140,200,0.3)" }}>
          <span style={{ fontSize: 11, color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontStyle: "italic", flex: 1 }}>
            Unknown cross — no hybrid type on record
          </span>
          <button onClick={() => setOpen(true)} style={{
            padding: "4px 14px", borderRadius: 6, border: "1px solid rgba(180,140,200,0.5)",
            background: "rgba(180,140,200,0.12)", color: "#c090d8",
            fontFamily: "'Cinzel', serif", fontSize: 10, letterSpacing: 1, cursor: "pointer",
          }}>✦ Name This Hybrid</button>
        </div>
      ) : (
        <div style={{ padding: 14, borderRadius: 8, background: "rgba(180,140,200,0.06)", border: "1px solid rgba(180,140,200,0.25)" }}>
          <div style={{ fontFamily: "'Cinzel', serif", fontSize: 11, color: "#c090d8", letterSpacing: 1, marginBottom: 10 }}>
            Register New Hybrid Type
          </div>
          {traits && (
            <div style={{ marginBottom: 10, fontSize: 11, color: "#8a7e6a", fontFamily: "'Crimson Text', serif", lineHeight: 1.8 }}>
              <div><strong style={{ color: "#c8b89a" }}>Based on {traits.parentA} × {traits.parentB} potential:</strong></div>
              <div>Colors: {traits.colorStr}</div>
              <div>Food: {traits.foodStr} · Temperament: {traits.temperamentStr}</div>
              <div>Clutches: {traits.clutchStr} · Eggs: {traits.eggStr}</div>
              <div style={{ color: "#7a7060" }}>{traits.wingNote}</div>
            </div>
          )}
          <input value={regName} onChange={e => setRegName(e.target.value)}
            placeholder="Hybrid type name (required)"
            style={{ width: "100%", padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(180,140,200,0.4)", background: "rgba(0,0,0,0.3)", color: "#e8dcc8", fontFamily: "'Crimson Text', serif", fontSize: 13, boxSizing: "border-box", marginBottom: 8 }} />
          <textarea value={regDesc} onChange={e => setRegDesc(e.target.value)}
            placeholder="Short description — focus on possibility, not certainty…"
            rows={2}
            style={{ width: "100%", padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(180,140,200,0.2)", background: "rgba(0,0,0,0.3)", color: "#e8dcc8", fontFamily: "'Crimson Text', serif", fontSize: 12, resize: "vertical", boxSizing: "border-box", marginBottom: 8 }} />
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={handleRegister} disabled={!regName.trim()} style={{
              padding: "6px 16px", borderRadius: 6, border: "none", cursor: regName.trim() ? "pointer" : "not-allowed",
              background: regName.trim() ? "#c090d8" : "rgba(255,255,255,0.05)",
              color: regName.trim() ? "#1a1a2e" : "#555", fontFamily: "'Cinzel', serif", fontSize: 11, fontWeight: 700, letterSpacing: 1,
            }}>Register Hybrid</button>
            <button onClick={() => { setOpen(false); setRegName(""); setRegDesc(""); }} style={{
              padding: "6px 12px", borderRadius: 6, border: "1px solid rgba(255,255,255,0.1)", background: "transparent",
              color: "#8a7e6a", fontFamily: "'Cinzel', serif", fontSize: 11, cursor: "pointer",
            }}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}

function SingleOffspringPanel({ result, label, compact, onSaved, detectedHybridName }) {
  const { addToRoster, addCustomHybrid, customHybrids = [] } = useRoster() || {};
  const [saving, setSaving] = useState(false);
  const [savedName, setSavedName] = useState("");
  const [savedGender, setSavedGender] = useState("unknown");
  const [markCarrier, setMarkCarrier] = useState(false);
  const [justSaved, setJustSaved] = useState(false);
  const [showSpec, setShowSpec] = useState(false);

  const autoLabel = result?.hybridLabel || detectedHybridName || "";
  const [savedLabel] = useState(autoLabel);

  const handleStartSaving = () => setSaving(true);

  const handleSave = () => {
    if (!savedName.trim()) return;
    const entry = resultToRosterEntry(result, savedName, autoLabel, (saving && markCarrier && mut === "none") ? "carrier" : (mut || undefined), savedGender);
    addToRoster(entry);
    setJustSaved(true);
    setSaving(false);
    setSavedName(""); setSavedGender("unknown"); setMarkCarrier(false);
    if (onSaved) onSaved(entry);
    setTimeout(() => setJustSaved(false), 3000);
  };

  if (!result || result.sameBreed) return null;

  const ac = result.attachmentColor;
  const acTag = ac && ac !== "Body Palette"
    ? <span style={{ fontSize: 11, color: "#8a7a50", fontStyle: "italic" }}> [{ac}]</span>
    : ac === "Body Palette"
      ? <span style={{ fontSize: 11, color: "#5a5a40", fontStyle: "italic" }}> [body palette]</span>
      : null;

  const mut = result.mutationStatus;
  const mutDef = result.mutationDef || (result.speciesKey ? MUTATIONS[result.speciesKey] : null);
  const isExpressed = mut === "expressed";
  const isCarrier = mut === "carrier";

  const parentKeys = result?.parentSpeciesKeys || [];

  const panelBg = isExpressed && result.mutationPalette
    ? `rgba(${parseInt(result.mutationPalette.primary.slice(1,3),16)},${parseInt(result.mutationPalette.primary.slice(3,5),16)},${parseInt(result.mutationPalette.primary.slice(5,7),16)},0.08)`
    : "rgba(200,148,63,0.05)";
  const panelBorder = isExpressed ? `1px solid ${result.mutationPalette?.primary || "#c8943f"}55` : "1px solid rgba(200,148,63,0.18)";

  return (
    <div style={{ background: panelBg, border: panelBorder, borderRadius: 10, padding: compact ? 14 : 22, marginBottom: compact ? 0 : 20 }}>

      {/* Label row */}
      {label && (
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
          <div style={{ fontFamily: "'Cinzel', serif", fontSize: 12, color: "#c8943f", letterSpacing: 1 }}>{label}</div>
          {autoLabel && (
            <span style={{ fontFamily: "'Cinzel', serif", fontSize: 10, color: "#8a7e6a", letterSpacing: 1, background: "rgba(255,255,255,0.05)", padding: "1px 8px", borderRadius: 10, border: "1px solid rgba(255,255,255,0.08)" }}>
              {autoLabel}
            </span>
          )}
        </div>
      )}
      {!label && autoLabel && !compact && (
        <div style={{ marginBottom: 8, fontFamily: "'Cinzel', serif", fontSize: 11, color: "#8a7e6a", letterSpacing: 1 }}>{autoLabel}</div>
      )}

      {/* Unknown hybrid registration — shown prominently when no label and not compact */}
      {!autoLabel && !compact && parentKeys[0] && parentKeys[1] && (
        <RegisterHybridBlock parentKeys={parentKeys} customHybrids={customHybrids} />
      )}

      {/* Mutation banner */}
      {(isExpressed || isCarrier) && !compact && (
        <div style={{ marginBottom: 12, padding: "8px 12px", borderRadius: 8, background: isExpressed ? "rgba(240,200,32,0.1)" : "rgba(255,255,255,0.04)", border: isExpressed ? "1px solid rgba(240,200,32,0.3)" : "1px solid rgba(255,255,255,0.08)" }}>
          <MutationBadge status={mut} mutationDef={mutDef} />
          {isExpressed && mutDef && <div style={{ marginTop: 4, fontSize: 12, color: "#c8b89a", fontFamily: "'Crimson Text', serif", fontStyle: "italic" }}>{mutDef.eggNote}</div>}
          {isCarrier && <div style={{ marginTop: 4, fontSize: 12, color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontStyle: "italic" }}>Visually normal — carries one copy of the recessive allele. Can pass mutation to offspring.</div>}
        </div>
      )}

      {/* Expressed palette */}
      {isExpressed && result.mutationPalette && (
        <div style={{ display: "flex", gap: 6, marginBottom: 12, alignItems: "center" }}>
          {Object.values(result.mutationPalette).map((hex, i) => (
            <div key={i} style={{ width: 20, height: 20, borderRadius: "50%", background: hex, border: "1px solid rgba(255,255,255,0.2)" }} />
          ))}
          <span style={{ fontSize: 11, color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontStyle: "italic" }}>Mutation palette</span>
        </div>
      )}

      {/* Trait grid */}
      <div style={{ display: "grid", gridTemplateColumns: compact ? "1fr 1fr" : "1fr", gap: compact ? "2px 16px" : 2, color: "#c8b89a", fontFamily: "'Crimson Text', serif", fontSize: 13, lineHeight: 1.7 }}>
        <div><strong style={{ color: "#e8dcc8" }}>Colors:</strong> {result.colorDisplay} {isCarrier && compact && <MutationBadge status="carrier" mutationDef={mutDef} size="small" />}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Food:</strong> {result.foodDisplay} · <strong style={{ color: "#e8dcc8" }}>Mood:</strong> {result.moodDisplay}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Wing Shape:</strong> <span style={{ color: "#d4c89a" }}>{result.wingShape?.result}</span></div>
        <div><strong style={{ color: "#e8dcc8" }}>Membrane Allele:</strong> <span style={{ color: "#d4c89a" }}>{result.wingMembrane?.result}</span></div>
        <div><strong style={{ color: "#e8dcc8" }}>Tail Tip:</strong> <span style={{ color: "#d4c89a" }}>{result.tailTip?.result}</span>{acTag}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Head Crest:</strong> <span style={{ color: "#d4c89a" }}>{result.headCrest?.result}</span>{acTag}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Spines:</strong> <span style={{ color: "#d4c89a" }}>{result.spineType?.result}</span>{acTag}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Eggs/Clutch:</strong> {result.eggDisplay}</div>
        {result.hasRBParent && (
          <div style={{ gridColumn: compact ? "span 2" : undefined }}>
            <strong style={{ color: "#e8dcc8" }}>Lifecycle:</strong>{" "}
            <span style={{ color: result.rbLifecycle ? "#c48ae0" : "#d4c89a" }}>{result.lifecycleStages?.join(" → ")}</span>
            {result.rbLifecycle ? <span style={{ fontSize: 11, color: "#9a6ac0", fontStyle: "italic" }}> ✦ metamorphic</span> : <span style={{ fontSize: 11, color: "#6a6050", fontStyle: "italic" }}> (standard lifecycle)</span>}
          </div>
        )}
      </div>

      {/* Bottom actions */}
      {!compact && (
        <div style={{ marginTop: 14, paddingTop: 12, borderTop: "1px solid rgba(255,255,255,0.06)" }}>

          {/* Save to Roster */}
          {justSaved ? (
            <div style={{ color: "#7ec87e", fontFamily: "'Cinzel', serif", fontSize: 12, letterSpacing: 1 }}>✓ Saved to Roster</div>
          ) : saving ? (
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-start" }}>
              <input value={savedName} onChange={e => setSavedName(e.target.value)} placeholder="Dragon name (required)"
                style={{ flex: "1 1 160px", padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(200,148,63,0.4)", background: "rgba(0,0,0,0.3)", color: "#e8dcc8", fontFamily: "'Crimson Text', serif", fontSize: 13 }} />
              <select value={savedGender} onChange={e => setSavedGender(e.target.value)} style={{
                padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(255,255,255,0.15)",
                background: "rgba(0,0,0,0.3)", color: savedGender === "female" ? "#e090c0" : savedGender === "male" ? "#90a8e0" : "#8a7e6a",
                fontFamily: "'Cinzel', serif", fontSize: 12, cursor: "pointer",
              }}>
                <option value="unknown">Gender?</option>
                <option value="female">♀ Female</option>
                <option value="male">♂ Male</option>
              </select>
              {/* Locked hybrid type badge — not editable */}
              {autoLabel && (
                <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "6px 10px", borderRadius: 6, background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.08)" }}>
                  <span style={{ fontSize: 11, color: "#c8943f", fontFamily: "'Cinzel', serif", letterSpacing: 1 }}>🔒 {autoLabel}</span>
                </div>
              )}
              {mut === "none" && result.speciesKey && MUTATIONS[result.speciesKey] && (
                <label style={{ display: "flex", alignItems: "center", gap: 6, color: "#8a7e6a", fontFamily: "'Cinzel', serif", fontSize: 11, cursor: "pointer", padding: "6px 0", whiteSpace: "nowrap" }}>
                  <input type="checkbox" checked={markCarrier} onChange={e => setMarkCarrier(e.target.checked)} style={{ cursor: "pointer" }} />
                  Mark as {MUTATIONS[result.speciesKey].shortName} Carrier
                </label>
              )}
              <button onClick={handleSave} disabled={!savedName.trim()} style={{
                padding: "6px 16px", borderRadius: 6, border: "none", cursor: savedName.trim() ? "pointer" : "not-allowed",
                background: savedName.trim() ? "#c8943f" : "rgba(255,255,255,0.05)",
                color: savedName.trim() ? "#1a1a2e" : "#555", fontFamily: "'Cinzel', serif", fontSize: 11, fontWeight: 700, letterSpacing: 1,
              }}>Save</button>
              <button onClick={() => { setSaving(false); setMarkCarrier(false); }} style={{ padding: "6px 12px", borderRadius: 6, border: "1px solid rgba(255,255,255,0.1)", background: "transparent", color: "#8a7e6a", fontFamily: "'Cinzel', serif", fontSize: 11, cursor: "pointer" }}>Cancel</button>
            </div>
          ) : (
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <button onClick={handleStartSaving} style={{
                padding: "6px 16px", borderRadius: 6, border: "1px solid rgba(200,148,63,0.3)", background: "transparent",
                color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, letterSpacing: 1, cursor: "pointer",
              }}>+ Save to Roster</button>
              {autoLabel && (
                <span style={{ fontSize: 11, color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontStyle: "italic" }}>
                  ✦ {autoLabel}
                </span>
              )}
            </div>
          )}
        </div>
      )}

      {/* Spec Sheet toggle — only on non-compact single results */}
      {!compact && (
        <div style={{ marginTop: 8 }}>
          <button onClick={() => setShowSpec(v => !v)} style={{
            background: "none", border: "none", cursor: "pointer",
            color: "#6a6050", fontFamily: "'Cinzel', serif", fontSize: 10, letterSpacing: 1, padding: 0,
          }}>
            {showSpec ? "▲ Hide Spec Sheet" : "▼ View Spec Sheet"}
          </button>
          {showSpec && (
            <div style={{ marginTop: 10 }}>
              <SpecSheetBlock data={result} name={savedName || autoLabel || result?.parents} />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function DragonCard({ entry, onRemove }) {
  const [expanded, setExpanded] = useState(false);
  const [editingPartner, setEditingPartner] = useState(false);
  const { partners = [], updateRoster } = useRoster() || {};
  const isWinged = entry.wingShape && entry.wingShape !== "none" && entry.wingShape !== "Wingless";
  const mutDef = entry.speciesKey ? MUTATIONS[entry.speciesKey] : null;
  const mutPalette = entry.mutationStatus === "expressed" && mutDef ? mutDef.palette : null;
  const cardBorder = mutPalette
    ? `1px solid ${mutPalette.primary}55`
    : entry.mutationStatus === "carrier"
      ? "1px solid rgba(255,255,255,0.18)"
      : "1px solid rgba(200,148,63,0.2)";

  const currentPartner = partners.find(p => p.id === entry.claimedBy);

  const handlePartnerChange = (partnerId) => {
    updateRoster(entry.id, { claimedBy: partnerId || null });
    setEditingPartner(false);
  };

  return (
    <div style={{
      background: mutPalette
        ? `rgba(${parseInt(mutPalette.primary.slice(1,3),16)},${parseInt(mutPalette.primary.slice(3,5),16)},${parseInt(mutPalette.primary.slice(5,7),16)},0.07)`
        : "rgba(255,255,255,0.03)",
      border: cardBorder,
      borderRadius: 12, padding: "18px 20px", position: "relative",
    }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 8 }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <div style={{ fontFamily: "'Cinzel', serif", fontSize: 16, color: "#e8dcc8", fontWeight: 700 }}>
              {entry.gender === "female" ? <span style={{ color: "#e090c0" }}>♀ </span> : entry.gender === "male" ? <span style={{ color: "#90a8e0" }}>♂ </span> : null}
              {entry.name}
            </div>
            {entry.mutationStatus && entry.mutationStatus !== "none" && (
              <MutationBadge status={entry.mutationStatus} mutationDef={mutDef} size="small" />
            )}
          </div>
          {entry.hybridLabel && (
            <div style={{ fontFamily: "'Cinzel', serif", fontSize: 11, color: "#c8943f", letterSpacing: 1, marginTop: 2 }}>{entry.hybridLabel}</div>
          )}
          <div style={{ fontSize: 12, color: "#6a6050", fontFamily: "'Crimson Text', serif", marginTop: 2, fontStyle: "italic" }}>
            {entry.parentage}
          </div>
          {/* Partner assignment */}
          <div style={{ marginTop: 4, display: "flex", alignItems: "center", gap: 6 }}>
            {editingPartner ? (
              <select
                autoFocus
                defaultValue={entry.claimedBy || ""}
                onChange={e => handlePartnerChange(e.target.value)}
                onBlur={() => setEditingPartner(false)}
                style={{
                  padding: "3px 8px", borderRadius: 6, border: "1px solid rgba(200,148,63,0.4)",
                  background: "rgba(0,0,0,0.4)", color: "#e8dcc8", fontFamily: "'Crimson Text', serif",
                  fontSize: 11, cursor: "pointer",
                }}
              >
                <option value="">No partner</option>
                {partners.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            ) : (
              <>
                <span style={{ fontSize: 11, color: currentPartner ? "#c8943f" : "#555", fontFamily: "'Cinzel', serif", letterSpacing: 1 }}>
                  {currentPartner ? `🤝 ${currentPartner.name}` : "No partner"}
                </span>
                {partners.length > 0 && (
                  <button onClick={() => setEditingPartner(true)} style={{ background: "none", border: "none", cursor: "pointer", color: "#6a6050", fontSize: 10, padding: "0 4px", fontFamily: "'Cinzel', serif", letterSpacing: 1 }}>
                    ✎
                  </button>
                )}
              </>
            )}
          </div>
        </div>
        <button onClick={onRemove} style={{ background: "none", border: "none", cursor: "pointer", color: "#5a4a3a", fontSize: 16, padding: "2px 6px" }} title="Remove">✕</button>
      </div>

      {/* Mutation palette swatch for expressed */}
      {mutPalette && (
        <div style={{ display: "flex", gap: 5, marginBottom: 10, alignItems: "center" }}>
          {Object.values(mutPalette).map((hex, i) => (
            <div key={i} style={{ width: 14, height: 14, borderRadius: "50%", background: hex, border: "1px solid rgba(255,255,255,0.2)" }} />
          ))}
          <span style={{ fontSize: 10, color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontStyle: "italic" }}>{mutDef.name} palette</span>
        </div>
      )}

      {/* Key traits */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "3px 12px", fontSize: 12, fontFamily: "'Crimson Text', serif", color: "#c8b89a", lineHeight: 1.6 }}>
        <div><span style={{ color: "#8a7e6a" }}>Colors:</span> {entry.colorDisplay}</div>
        <div><span style={{ color: "#8a7e6a" }}>Food:</span> {entry.foodDisplay}</div>
        <div><span style={{ color: "#8a7e6a" }}>Mood:</span> {entry.moodDisplay}</div>
        <div><span style={{ color: "#8a7e6a" }}>Clutch:</span> {entry.clutchDisplay} max · {entry.eggDisplay} eggs</div>
        <div><span style={{ color: "#8a7e6a" }}>Wings:</span> {isWinged ? entry.wingShape : "Wingless"}</div>
        <div>
          <span style={{ color: "#8a7e6a" }}>Membrane:</span>{" "}
          {entry.attachmentColor && entry.attachmentColor !== "Body Palette"
            ? <span>{entry.attachmentColor}</span>
            : <span style={{ color: "#6a6050" }}>Body Palette</span>
          }
          {entry.wingMembrane && entry.wingMembrane !== "null" && entry.wingMembrane !== entry.attachmentColor && (
            <span style={{ color: "#6a5040", fontSize: 10, marginLeft: 4 }}>[{entry.wingMembrane}]</span>
          )}
        </div>
        <div><span style={{ color: "#8a7e6a" }}>Tail Tip:</span> {entry.tailTip || "—"}</div>
        <div><span style={{ color: "#8a7e6a" }}>Head Crest:</span> {entry.headCrest || "—"}</div>
        <div style={{ gridColumn: "span 2" }}><span style={{ color: "#8a7e6a" }}>Spines:</span> {entry.spineType || "—"}
          {entry.attachmentColor && entry.attachmentColor !== "Body Palette" && (
            <span style={{ color: "#6a5040", fontSize: 10, fontStyle: "italic", marginLeft: 6 }}>· attachment color: {entry.attachmentColor}</span>
          )}
        </div>
      </div>

      <button onClick={() => setExpanded(v => !v)} style={{ marginTop: 10, background: "none", border: "none", cursor: "pointer", color: "#6a6050", fontSize: 11, fontFamily: "'Cinzel', serif", letterSpacing: 1, padding: 0 }}>
        {expanded ? "▲ Hide Spec Sheet" : "▼ Spec Sheet"}
      </button>

      {expanded && (
        <div style={{ marginTop: 10 }}>
          <SpecSheetBlock data={entry} name={entry.name} />
        </div>
      )}
    </div>
  );
}

// ============================================================
// SHARED FILTER UTILITIES
// ============================================================

// Derives a display species key from a roster entry's parentage/hybridLabel
// Returns null if it can't be determined
function entrySpeciesKey(entry) {
  // Pure breed
  if (entry.speciesKey) return entry.speciesKey;
  // Try to match hybridLabel against HYBRIDS
  if (entry.hybridLabel) {
    const match = Object.entries(HYBRIDS).find(([, h]) => h.name === entry.hybridLabel);
    if (match) return match[0]; // hybrid key
  }
  return null;
}

// Does a roster entry have a given base species in its lineage?
function entryMatchesSpecies(entry, speciesKey, customHybrids = []) {
  const key = entrySpeciesKey(entry);
  if (!key) return false;
  const lineage = resolveBaseSpecies(key, customHybrids);
  return lineage.has(speciesKey);
}

function FilterBar({ selected, onToggle, onClear, extraFilters, onExtraChange, resultCount, totalCount }) {
  return (
    <div style={{ marginBottom: 20, padding: "14px 16px", background: "rgba(255,255,255,0.02)", borderRadius: 10, border: "1px solid rgba(255,255,255,0.06)" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <span style={{ color: "#8a7e6a", fontFamily: "'Cinzel', serif", fontSize: 10, letterSpacing: 2, textTransform: "uppercase" }}>
          Filter by Lineage {selected.size > 0 && <span style={{ color: "#c8943f" }}>({selected.size} selected)</span>}
        </span>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <span style={{ fontSize: 11, color: "#6a6050", fontFamily: "'Crimson Text', serif" }}>
            {resultCount} / {totalCount}
          </span>
          {(selected.size > 0 || Object.values(extraFilters || {}).some(v => v !== "all")) && (
            <button onClick={onClear} style={{ background: "none", border: "none", cursor: "pointer", color: "#8a7e6a", fontFamily: "'Cinzel', serif", fontSize: 10, letterSpacing: 1, padding: 0 }}>
              Clear all ✕
            </button>
          )}
        </div>
      </div>

      {/* Species pills */}
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: extraFilters ? 10 : 0 }}>
        {speciesOrder.map(k => {
          const isOn = selected.has(k);
          const s = SPECIES[k];
          return (
            <button key={k} onClick={() => onToggle(k)} style={{
              padding: "4px 12px", borderRadius: 20, cursor: "pointer",
              fontFamily: "'Cinzel', serif", fontSize: 10, letterSpacing: 1,
              border: `1px solid ${isOn ? accentColor(s.palette) : "rgba(255,255,255,0.1)"}`,
              background: isOn ? `${accentColor(s.palette)}28` : "transparent",
              color: isOn ? accentColor(s.palette) : "#8a7e6a",
              transition: "all 0.15s",
            }}>
              {s.name.replace(" Dragon","").replace(" Butterfly Dragon"," Butterfly")}
            </button>
          );
        })}
      </div>

      {/* Extra filters (gender, mutation, etc.) */}
      {extraFilters && (
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
          {extraFilters.gender !== undefined && (
            <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
              <span style={{ color: "#6a6050", fontFamily: "'Cinzel', serif", fontSize: 9, letterSpacing: 1 }}>GENDER</span>
              {["all","female","male","unknown"].map(v => (
                <button key={v} onClick={() => onExtraChange("gender", v)} style={{
                  padding: "3px 10px", borderRadius: 12, cursor: "pointer", fontSize: 10,
                  fontFamily: "'Cinzel', serif", letterSpacing: 1,
                  border: `1px solid ${extraFilters.gender === v ? "#c8943f" : "rgba(255,255,255,0.08)"}`,
                  background: extraFilters.gender === v ? "rgba(200,148,63,0.15)" : "transparent",
                  color: v === "female" ? "#e090c0" : v === "male" ? "#90a8e0" : extraFilters.gender === v ? "#c8943f" : "#6a6050",
                }}>
                  {v === "all" ? "Any" : v === "female" ? "♀" : v === "male" ? "♂" : "?"}
                </button>
              ))}
            </div>
          )}
          {extraFilters.mutation !== undefined && (
            <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
              <span style={{ color: "#6a6050", fontFamily: "'Cinzel', serif", fontSize: 9, letterSpacing: 1 }}>MUTATION</span>
              {["all","expressed","carrier","none"].map(v => (
                <button key={v} onClick={() => onExtraChange("mutation", v)} style={{
                  padding: "3px 10px", borderRadius: 12, cursor: "pointer", fontSize: 10,
                  fontFamily: "'Cinzel', serif", letterSpacing: 1,
                  border: `1px solid ${extraFilters.mutation === v ? "#c8943f" : "rgba(255,255,255,0.08)"}`,
                  background: extraFilters.mutation === v ? "rgba(200,148,63,0.15)" : "transparent",
                  color: v === "expressed" ? "#f0c820" : v === "carrier" ? "#8a7e6a" : extraFilters.mutation === v ? "#c8943f" : "#6a6050",
                }}>
                  {v === "all" ? "Any" : v === "expressed" ? "✦ Expressed" : v === "carrier" ? "◇ Carrier" : "Normal"}
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function RosterPanel() {
  const { roster, removeFromRoster, customHybrids = [] } = useRoster();
  const [selectedSpecies, setSelectedSpecies] = useState(new Set());
  const [extraFilters, setExtraFilters] = useState({ gender: "all", mutation: "all" });

  const toggleSpecies = (k) => setSelectedSpecies(prev => {
    const next = new Set(prev);
    if (next.has(k)) next.delete(k); else next.add(k);
    return next;
  });

  const clearAll = () => { setSelectedSpecies(new Set()); setExtraFilters({ gender: "all", mutation: "all" }); };
  const changeExtra = (key, val) => setExtraFilters(prev => ({ ...prev, [key]: val }));

  const filtered = roster.filter(entry => {
    if (selectedSpecies.size > 0) {
      const matches = [...selectedSpecies].every(s => entryMatchesSpecies(entry, s, customHybrids));
      if (!matches) return false;
    }
    if (extraFilters.gender !== "all" && (entry.gender || "unknown") !== extraFilters.gender) return false;
    if (extraFilters.mutation !== "all" && (entry.mutationStatus || "none") !== extraFilters.mutation) return false;
    return true;
  });

  if (roster.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "60px 20px", color: "#6a6050" }}>
        <div style={{ fontSize: 40, marginBottom: 16 }}>📋</div>
        <h3 style={{ fontFamily: "'Cinzel', serif", color: "#8a7e6a", fontSize: 16, margin: "0 0 8px" }}>No Dragons Saved Yet</h3>
        <p style={{ fontFamily: "'Crimson Text', serif", fontSize: 14, maxWidth: 400, margin: "0 auto", lineHeight: 1.7 }}>
          Breed dragons in the Breeding Lab and click <em>Save to Roster</em> on any result.
          Saved individuals can then be used as parents for second-generation breeding.
        </p>
      </div>
    );
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 16 }}>
        <div>
          <h2 style={{ margin: "0 0 4px", fontFamily: "'Cinzel', serif", color: "#e8dcc8", fontSize: 22 }}>Dragon Roster</h2>
          <p style={{ margin: 0, color: "#8a7e6a", fontSize: 14 }}>
            {roster.length} individual{roster.length !== 1 ? "s" : ""} saved · usable as parents in the Breeding Lab.
          </p>
        </div>
      </div>

      <FilterBar
        selected={selectedSpecies}
        onToggle={toggleSpecies}
        onClear={clearAll}
        extraFilters={extraFilters}
        onExtraChange={changeExtra}
        resultCount={filtered.length}
        totalCount={roster.length}
      />

      {filtered.length === 0 ? (
        <div style={{ textAlign: "center", padding: "30px 20px", color: "#6a6050", fontFamily: "'Crimson Text', serif", fontSize: 14 }}>
          No dragons match the current filters.
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(340px, 1fr))", gap: 16 }}>
          {filtered.map(entry => (
            <DragonCard key={entry.id} entry={entry} onRemove={() => removeFromRoster(entry.id)} />
          ))}
        </div>
      )}
    </div>
  );
}

function SameBreedEggPanel({ egg, label }) {
  const { addToRoster } = useRoster() || {};
  const [saving, setSaving] = useState(false);
  const [savedName, setSavedName] = useState("");
  const [savedGender, setSavedGender] = useState("unknown");
  const [markCarrier, setMarkCarrier] = useState(false);
  const [justSaved, setJustSaved] = useState(false);

  const mutDef = egg.speciesKey ? MUTATIONS[egg.speciesKey] : null;

  const handleSave = () => {
    if (!savedName.trim()) return;
    const mutStatus = markCarrier ? "carrier" : "none";
    const entry = resultToRosterEntry(egg, savedName, "", mutStatus, savedGender);
    addToRoster(entry);
    setJustSaved(true);
    setSaving(false);
    setSavedName(""); setSavedGender("unknown"); setMarkCarrier(false);
    setTimeout(() => setJustSaved(false), 3000);
  };

  return (
    <div style={{ background: "rgba(200,148,63,0.04)", border: "1px solid rgba(200,148,63,0.15)", borderRadius: 10, padding: 16 }}>
      {label && <div style={{ fontFamily: "'Cinzel', serif", fontSize: 12, color: "#c8943f", marginBottom: 8, letterSpacing: 1 }}>{label}</div>}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "2px 16px", color: "#c8b89a", fontFamily: "'Crimson Text', serif", fontSize: 13, lineHeight: 1.7 }}>
        <div><strong style={{ color: "#e8dcc8" }}>Species:</strong> {egg.species}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Colors:</strong> {egg.colors}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Food:</strong> {egg.food}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Temperament:</strong> {egg.temperament}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Clutch max:</strong> {egg.clutches}</div>
        <div><strong style={{ color: "#e8dcc8" }}>Eggs/Clutch:</strong> {egg.eggs}</div>
      </div>

      {/* Save to Roster */}
      {addToRoster && (
        <div style={{ marginTop: 12, paddingTop: 10, borderTop: "1px solid rgba(255,255,255,0.06)" }}>
          {justSaved ? (
            <div style={{ color: "#7ec87e", fontFamily: "'Cinzel', serif", fontSize: 12, letterSpacing: 1 }}>✓ Saved to Roster</div>
          ) : saving ? (
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
              <input
                value={savedName} onChange={e => setSavedName(e.target.value)}
                placeholder="Dragon name (required)"
                style={{ flex: "1 1 160px", padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(200,148,63,0.4)", background: "rgba(0,0,0,0.3)", color: "#e8dcc8", fontFamily: "'Crimson Text', serif", fontSize: 13 }}
              />
              <select value={savedGender} onChange={e => setSavedGender(e.target.value)} style={{
                padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(255,255,255,0.15)",
                background: "rgba(0,0,0,0.3)", color: savedGender === "female" ? "#e090c0" : savedGender === "male" ? "#90a8e0" : "#8a7e6a",
                fontFamily: "'Cinzel', serif", fontSize: 12, cursor: "pointer",
              }}>
                <option value="unknown">Gender?</option>
                <option value="female">♀ Female</option>
                <option value="male">♂ Male</option>
              </select>
              {mutDef && (
                <label style={{ display: "flex", alignItems: "center", gap: 6, color: "#8a7e6a", fontFamily: "'Cinzel', serif", fontSize: 11, cursor: "pointer", whiteSpace: "nowrap" }}>
                  <input type="checkbox" checked={markCarrier} onChange={e => setMarkCarrier(e.target.checked)} style={{ cursor: "pointer" }} />
                  Mark as {mutDef.shortName} Carrier
                </label>
              )}
              <button onClick={handleSave} disabled={!savedName.trim()} style={{
                padding: "6px 16px", borderRadius: 6, border: "none", cursor: savedName.trim() ? "pointer" : "not-allowed",
                background: savedName.trim() ? "#c8943f" : "rgba(255,255,255,0.05)",
                color: savedName.trim() ? "#1a1a2e" : "#555", fontFamily: "'Cinzel', serif", fontSize: 11, fontWeight: 700, letterSpacing: 1,
              }}>Save</button>
              <button onClick={() => { setSaving(false); setMarkCarrier(false); }} style={{ padding: "6px 12px", borderRadius: 6, border: "1px solid rgba(255,255,255,0.1)", background: "transparent", color: "#8a7e6a", fontFamily: "'Cinzel', serif", fontSize: 11, cursor: "pointer" }}>Cancel</button>
            </div>
          ) : (
            <button onClick={() => setSaving(true)} style={{
              padding: "6px 16px", borderRadius: 6, border: "1px solid rgba(200,148,63,0.3)", background: "transparent",
              color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, letterSpacing: 1, cursor: "pointer",
            }}>+ Save to Roster</button>
          )}
        </div>
      )}
    </div>
  );
}

function BreedingLab() {
  const { roster, customHybrids = [], discoverHybrid } = useRoster() || { roster: [], customHybrids: [] };

  // Parent state: null | { type: "species", key } | { type: "roster", id }
  const [parent1, setParent1] = useState(null);
  const [parent2, setParent2] = useState(null);
  const [motherSlot, setMotherSlot] = useState("parent1"); // "parent1" | "parent2"
  const [result, setResult] = useState(null);
  const [history, setHistory] = useState([]);

  // Resolve a parent selector value string to a parent state object
  const parseParentVal = (val) => {
    if (!val) return null;
    if (val.startsWith("s:")) return { type: "species", key: val.slice(2) };
    if (val.startsWith("r:")) return { type: "roster", id: val.slice(2) };
    return null;
  };
  const parentToVal = (p) => p ? (p.type === "species" ? `s:${p.key}` : `r:${p.id}`) : "";

  // Get a breeding proxy from a parent selector
  const resolveProxy = (parent) => {
    if (!parent) return null;
    if (parent.type === "species") {
      const s = SPECIES[parent.key];
      return s ? speciesProxy(s, parent.key) : null;
    }
    if (parent.type === "roster") {
      const entry = roster.find(e => e.id === parent.id);
      return entry ? rosterEntryToProxy(entry, customHybrids) : null;
    }
    return null;
  };

  const isSameSpecies = parent1?.type === "species" && parent2?.type === "species" && parent1.key === parent2.key;

  const detectedHybridName = useMemo(() => {
    const p1 = resolveProxy(parent1);
    const p2 = resolveProxy(parent2);
    if (!p1 || !p2 || isSameSpecies) return null;
    const k1 = p1.speciesKey;
    const k2 = p2.speciesKey;
    if (!k1 || !k2) return null;
    return resolveHybridName(k1, k2, customHybrids);
  }, [parent1, parent2, roster, customHybrids]);

  const doBreed = () => {
    const p1 = resolveProxy(parent1);
    const p2 = resolveProxy(parent2);
    if (!p1 || !p2) return null;
    if (isSameSpecies) return breedDragons(parent1.key, parent2.key);
    return breedTwo(p1, p2, customHybrids);
  };

  const handleBreed = () => {
    if (!parent1 || !parent2) return;
    const r = doBreed();
    if (!r) return;
    setResult(r);
    if (r.hybridLabel) discoverHybrid(r.hybridLabel);
    setHistory((prev) => [{ ...r, id: Date.now() }, ...prev].slice(0, 10));
  };

  const selectStyle = {
    width: "100%", padding: "10px 12px", borderRadius: 8, border: "1px solid rgba(255,255,255,0.12)",
    background: "rgba(0,0,0,0.3)", color: "#e8dcc8", fontFamily: "'Crimson Text', serif", fontSize: 14, cursor: "pointer",
  };

  const genderBtnStyle = (active, isFemale) => ({
    padding: "4px 10px", borderRadius: 6, border: `1px solid ${active ? (isFemale ? "rgba(220,130,180,0.6)" : "rgba(130,160,220,0.6)") : "rgba(255,255,255,0.1)"}`,
    background: active ? (isFemale ? "rgba(220,130,180,0.15)" : "rgba(130,160,220,0.15)") : "transparent",
    color: active ? (isFemale ? "#e090c0" : "#90a8e0") : "#555",
    fontFamily: "'Cinzel', serif", fontSize: 11, cursor: "pointer", letterSpacing: 1,
  });

  const ParentSelect = ({ slot, value, onChange, label }) => {
    const isMother = motherSlot === slot;
    return (
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
          <label style={{ color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 11, textTransform: "uppercase", letterSpacing: 2 }}>{label}</label>
          <div style={{ display: "flex", gap: 4 }}>
            <button style={genderBtnStyle(isMother, true)} onClick={() => setMotherSlot(slot)}>♀ Mother</button>
            <button style={genderBtnStyle(!isMother, false)} onClick={() => setMotherSlot(slot === "parent1" ? "parent2" : "parent1")}>♂ Father</button>
          </div>
        </div>
        <select value={parentToVal(value)} onChange={e => onChange(parseParentVal(e.target.value))} style={selectStyle}>
          <option value="">Select parent…</option>
          <optgroup label="Core Species">
            {speciesOrder.map(k => <option key={k} value={`s:${k}`}>{SPECIES[k].name}</option>)}
          </optgroup>
          {roster.length > 0 && (
            <optgroup label="Dragon Roster">
              {roster.map(d => (
                <option key={d.id} value={`r:${d.id}`}>
                  {d.gender === "female" ? "♀ " : d.gender === "male" ? "♂ " : ""}{d.name}{d.hybridLabel ? ` · ${d.hybridLabel}` : ""} ({d.parentage})
                </option>
              ))}
            </optgroup>
          )}
        </select>
        {isMother && (
          <div style={{ marginTop: 4, fontSize: 11, color: "#9a7e6a", fontFamily: "'Crimson Text', serif", fontStyle: "italic" }}>
            Mother — clutch size from her egg genetics
          </div>
        )}
      </div>
    );
  };

  const canBreed = parent1 && parent2;

  return (
    <div>
      <div style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.08)", borderRadius: 12, padding: 28, marginBottom: 20 }}>
        <h3 style={{ margin: "0 0 6px", fontFamily: "'Cinzel', serif", color: "#c8943f", fontSize: 16 }}>Breeding Chamber</h3>
        <p style={{ margin: "0 0 20px", color: "#8a7e6a", fontFamily: "'Crimson Text', serif", fontSize: 13 }}>
          Select two parents and breed a single offspring. Save individuals to the Roster, then use the Nursery to bond a pair and generate full clutches.
          {roster.length > 0 && <span style={{ color: "#c8943f" }}> {roster.length} roster individual{roster.length !== 1 ? "s" : ""} available.</span>}
        </p>

        <div style={{ display: "grid", gridTemplateColumns: "1fr auto 1fr", gap: 16, alignItems: "start", marginBottom: 20 }}>
          <ParentSelect slot="parent1" value={parent1} onChange={setParent1} label="Parent One" />
          <div style={{ color: "#c8943f", fontSize: 24, fontFamily: "'Cinzel', serif", paddingTop: 32 }}>×</div>
          <ParentSelect slot="parent2" value={parent2} onChange={setParent2} label="Parent Two" />
        </div>

        <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
          <button onClick={handleBreed} disabled={!canBreed} style={{
            padding: "10px 28px", borderRadius: 8, border: "none", cursor: canBreed ? "pointer" : "not-allowed",
            background: canBreed ? "linear-gradient(135deg, #c8943f, #a0742f)" : "rgba(255,255,255,0.05)",
            color: canBreed ? "#1a1a2e" : "#555", fontFamily: "'Cinzel', serif", fontSize: 13, fontWeight: 700, textTransform: "uppercase", letterSpacing: 1, transition: "all 0.2s",
          }}>Breed One</button>
          {result && !result.sameBreed && (
            <button onClick={handleBreed} style={{ padding: "10px 28px", borderRadius: 8, border: "1px solid rgba(200,148,63,0.3)", cursor: "pointer", background: "transparent", color: "#c8943f", fontFamily: "'Cinzel', serif", fontSize: 13, letterSpacing: 1 }}>Reroll</button>
          )}
        </div>
      </div>

      {result && result.sameBreed && (
        <div style={{ background: "rgba(200,148,63,0.06)", border: "1px solid rgba(200,148,63,0.2)", borderRadius: 12, padding: 24, marginBottom: 20 }}>
          <h4 style={{ margin: "0 0 8px", fontFamily: "'Cinzel', serif", color: "#c8943f", fontSize: 15 }}>Same-Breed Result</h4>
          <SameBreedEggPanel egg={result} />
        </div>
      )}

      {result && !result.sameBreed && (
        <div style={{ background: "rgba(200,148,63,0.06)", border: "1px solid rgba(200,148,63,0.2)", borderRadius: 12, padding: 24, marginBottom: 20 }}>
          <h4 style={{ margin: "0 0 4px", fontFamily: "'Cinzel', serif", color: "#c8943f", fontSize: 15 }}>Offspring · {result.parents}</h4>
          <SingleOffspringPanel result={result} detectedHybridName={detectedHybridName} />
          {result.allColorOutcomes && (
            <div style={{ marginTop: 8 }}>
              <div style={{ color: "#8a7e6a", fontSize: 11, marginBottom: 4 }}>All possible color outcomes:</div>
              <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
                {[...new Set(result.allColorOutcomes)].map((c, i) => (
                  <span key={i} style={{ padding: "2px 6px", borderRadius: 3, fontSize: 10, fontFamily: "'Courier New', monospace", background: "rgba(0,0,0,0.3)", color: "#c8b89a", border: "1px solid rgba(255,255,255,0.06)" }}>{c}</span>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {history.length > 0 && (
        <div>
          <h4 style={{ fontFamily: "'Cinzel', serif", color: "#8a7e6a", fontSize: 13, marginBottom: 10 }}>Recent Breeding History</h4>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {history.map(h => (
              <div key={h.id} style={{ padding: "8px 14px", borderRadius: 6, fontSize: 12, fontFamily: "'Crimson Text', serif", background: "rgba(255,255,255,0.02)", border: "1px solid rgba(255,255,255,0.05)", color: "#8a7e6a" }}>
                {h.sameBreed ? <span>{h.species} (same breed)</span> : <span>{h.parents} → <span style={{ color: "#c8943f" }}>{h.colorCode}</span> · {h.foodDisplay} · {h.moodDisplay}</span>}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================================
// SPEC SHEET — reusable display, driven from a roster entry OR a breed result
// ============================================================

